INSERT INTO `block_content_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('basic', 0, 1, 1, 'en', 0, '<h2 class=\"mission-title\">About <span class=\"accent-text\">Us</span></h2><p class=\"mission-text\">Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.</p>', '', 'full_html'),
('basic', 0, 2, 2, 'en', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img class=\"modi-image\" src=\"http://localhost/cbc/themes/cbc/img/pm_modi.jpg\" alt=\"Prime Minister Narendra Modi\" width=\"934\" height=\"452\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">\"National Programme for Civil Services Capacity Building will radically improve the Human Resource Management practices in the Government through state of the art infrastructure to augment the capacity of Civil Servants.\"</p><p class=\"modi-message-attribution\">- Hon\'ble Prime Minister</p></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'en', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"http://localhost/cbc/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">\"National Standards for Civil Service Training Institutes 2.0 is not just a compliance tool—it is a transformative step toward institutional excellence.\"</p><div class=\"jitender-name-badge\"><p>Dr. Jitendra Singh</p><p class=\"f-6\">Hon\'ble Minister of State</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 4, 4, 'en', 0, '<p><i class=\"fas fa-map-marker-alt\"></i> 7th Floor, NDCC-II Building, New Delhi, India</p><p><i class=\"fas fa-phone-alt\"></i> +91 11 2309 3200</p><p><i class=\"fas fa-envelope\"></i> info@cbc.gov.in</p>', '', 'full_html'),
('basic', 0, 5, 5, 'en', 0, '<h2>Capacity Building Commission</h2><p>Strengthening governance and empowering civil services through innovation, training, and collaborative leadership under Mission Karmayogi.</p><div class=\"social-icons\"><a href=\"#\"><i class=\"fab fa-x-twitter\"></i></a> <a href=\"#\"><i class=\"fab fa-linkedin\"></i></a> <a href=\"#\"><i class=\"fab fa-instagram\"></i></a> <a href=\"#\"><i class=\"fab fa-facebook\"></i></a></div>', '', 'full_html'),
('basic', 0, 7, 7, 'en', 0, '<div class=\"section-body\"><div class=\"social-grid\"><!-- Twitter/X Feed --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" id=\"twitter-widget-container\"><p style=\"color:white;font-size:0.7rem;margin:0;text-align:center;\"><a href=\"https://twitter.com/CBC_MK\"><strong>@CBC_MK</strong></a></p><p style=\"color:rgba(255,255,255,0.9);font-size:0.6rem;line-height:1;margin:0px 0 0 0;text-align:center;\"><a href=\"https://twitter.com/CBC_MK\">Visit our Twitter/X</a></p><div style=\"background-color:white;border-radius:12px;color:#000;font-size:0.6rem;margin-top:10px;\"><a href=\"https://twitter.com/CBC_MK\"><strong>Follow Us</strong></a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-x-twitter\"></i> Twitter/X</div></div><!-- LinkedIn Company Page --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" id=\"linkedin-widget-container\"><div class=\"linkedin-company-feed\" style=\"height:100%;\"><p style=\"margin-bottom:0px;\"><a style=\"*/justify-content:center;*/text-decoration:none;/* height:100%;/* padding:12px 8px;align-items:center;background-color:#e8e6e1;color:#0077b5;display:flex;flex-direction:column;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-linkedin\" style=\"color:#0077b5;font-size:1.6rem;margin-bottom:8px;\"></i>&nbsp;</a></p><p style=\"color:#0077b5;font-size:0.7rem;line-height:1.2;margin:0;text-align:center;\"><a style=\"*/text-decoration:none;/* padding:12px 8px;align-items:center;background-color:#e8e6e1;color:#0077b5;display:flex;flex-direction:column;height:100%;justify-content:center;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\"><strong style=\"font-size:10px;\">Capacity Building Commission</strong></a></p><p style=\"color:#666;font-size:0.6rem;line-height:1.3;margin:0px 0 0 0;text-align:center;\"><a style=\"align-items:center;background-color:#e8e6e1;color:#0077b5;display:flex;flex-direction:column;font-size:10px;padding:2px 8px;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\">Visit our LinkedIn</a></p><div style=\"background-color:#fffff;border-radius:12px;color:white;font-size:0.6rem;\"><a style=\"align-items:center;color:#ffffff;display:flex;flex-direction:column;height:100%;justify-content:center;text-decoration:none;\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Follow Us</strong></a></div></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-linkedin-in\"></i> LinkedIn</div></div><!-- Instagram Feed --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" id=\"instagram-widget-container\"><p style=\"margin-bottom:0px;\"><a style=\"align-items:center;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-instagram\" style=\"color:white;font-size:1.6rem;margin-bottom:8px;\"></i></a></p><p style=\"color:white;font-size:0.4rem;line-height:1.2;margin:0;text-align:center;\"><a style=\"align-items:center;display:flex;flex-direction:column;font-size:10px;height:100%;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>@capacitybuildingcommission</strong></a></p><p style=\"color:rgba(255,255,255,0.95);font-size:0.6rem;line-height:1.3;margin:6px 0 0 0;text-align:center;\"><a style=\"align-items:center;display:flex;flex-direction:column;height:100%;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\">Visit our Instagram</a></p><div style=\"background-color:#0077b5;border-radius:12px;color:#E4405F;font-size:0.6rem;margin-top:10px;\"><a style=\"align-items:center;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Follow Us</strong></a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-instagram\"></i> Instagram</div></div><!-- Facebook Feed --><div class=\"social-card bg-white rounded-3 shadow-sm\"><div class=\"w-100 social-embed-container\" id=\"facebook-widget-container\"><p style=\"margin-bottom:0px;padding-bottom:0px;\"><a style=\"align-items:center;background-color:#cce7ff;color:#1877f2;cursor:pointer;display:flex;flex-direction:column;height:100%;justify-content:center;text-decoration:none;\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-facebook\" style=\"/* margin-bottom:8px;color:#1877f2;font-size:1.6rem;\"></i></a></p><p style=\"margin-bottom:0px;text-align:center;\"><a style=\"align-items:center;background-color:#cce7ff;color:#1877f2;cursor:pointer;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\"><strong style=\"font-size:10px;\">Capacity Building Commission</strong></a></p><p style=\"color:#666;font-size:0.6rem;line-height:1.3;margin-bottom:0px;text-align:center;\"><a style=\"align-items:center;background-color:#cce7ff;color:#1877f2;cursor:pointer;display:flex;flex-direction:column;font-size:10px;height:100%;justify-content:center;line-height:0.8;text-decoration:none;\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\">Visit our Facebook</a></p><div style=\"background-color:#1877f2;border-radius:12px;color:white;font-size:0.6rem;\"><a style=\"align-items:center;color:#1877f2;cursor:pointer;display:flex;flex-direction:column;justify-content:center;text-decoration:none;\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\"><strong>Follow Us</strong></a></div></div><div class=\"social-overlay text-white\"><i class=\"fab fa-facebook\"></i> Facebook</div></div></div></div>', '', 'full_html'),
('basic', 0, 8, 8, 'en', 0, '<section class=\"stats-section\"><div class=\"stat\"><h2 class=\"count\" data-target=\"13949992\">0</h2><p>Users Onboarded on iGOT</p></div><div class=\"stat\"><h2 class=\"count\" data-target=\"108\">0</h2><p>Ministries and Depts. Engaged</p></div><div class=\"stat\"><h2 class=\"count\" data-target=\"195\">0</h2><p>Training Institutes Accredited</p></div><div class=\"stat\"><h2 class=\"count\" data-target=\"27\">0</h2><p>MoUs (States/UTs)</p></div><div class=\"stat\"><h2 class=\"count\" data-target=\"3679\">0</h2><p>Total Courses</p></div></section>', '', 'full_html'),
('basic', 0, 9, 9, 'en', 0, '<div class=\"message-preview-letter\"><div class=\"preview-letter-header-new\"><div class=\"preview-letter-title-wrapper\"><h4 class=\"preview-letter-title-new\">FROM THE&nbsp;<br>CHAIRPERSON\'S DESK<span class=\"preview-pencil-icon\">✏️</span></h4></div><div class=\"preview-chairperson-photo\"><img class=\"preview-chairperson-img\" src=\"/cbc/sites/default/files/2025-12/cbc%20chairman_1.png\" alt=\"Ms. S. Radha Chauhan\"></div></div><div class=\"preview-letter-divider\">&nbsp;</div><div class=\"preview-letter-content\"><div class=\"preview-letter-text\"><p class=\"preview-letter-intro\">Let us join hands for continuously empowering our learning eco-system.</p><p class=\"preview-letter-paragraph\">Mission Karmayogi is a path-breaking and a first of its kind initiative envisioned by Hon\'ble Prime Minister Shri Narendra Modi, in the year 2020. Since its inception, Mission Karmayogi team has functioned with dedication towards developing an eco-system which strives to enable lifelong learning for the Civil Servants, who are an important link for citizen-centric delivery of services. The Capacity Building Commission, established on 1st April, 2021, functions at the core of Mission Karmayogi, through policy frameworks laying foundation of capacity building initiatives.</p><p class=\"preview-letter-paragraph\">It gives me immense pride to lead the efforts of Capacity Building Commission. We together need to take this journey ahead.</p><p class=\"preview-letter-paragraph\">As we are aware, civil servants perform in a ever-growing and sometimes uncertain environment. The emerging and new technologies are not only providing unseen opportunities, but at the same time posing challenges never imagined before. As civil servants, our duty is to deliver in any given situation and upkeep the trust of the citizens. Continuous capacity building is the key to strive through any challenge that might come and to optimally utilise the opportunities that might go unutilised if we are not well-equipped to handle them.</p><p class=\"preview-letter-paragraph\">It is pertinent to mention here that we all need to come together to continuously build a learning eco-system which enables our manpower to be ready to face and utilise any given situation to the best advantage of the citizens. Our civil servants across the Central and State Governments need to be a part of this learning process. The wider the chain, the greater the impact will be.</p><p class=\"preview-letter-paragraph\">We at the Commission are continuously functioning to arrive at the frameworks and policies that emphasise upon innovation, foresight and research. We wish to build an eco-system where we learn from the capacity building best practices of each other and institutionalise them as part of our eco-system.</p><p class=\"preview-letter-paragraph\">We emphasise on the capacity enhancement and upgrading of our Training Institute in all aspects while acknowledging that they are the backbone of our learning framework.</p><p class=\"preview-letter-paragraph\">I feel that excellence should not only be institutionalised but also celebrated by all of us. I wish to acknowledge the efforts put by you, which has set an example for other to strive towards excellence.</p><p class=\"preview-letter-paragraph\">I consider all my stakeholder an important part of my team &amp; journey and we are open to any feedback, suggestions that might help us grow together.</p></div></div><div class=\"preview-letter-signature\"><div class=\"preview-signature-wishes\">Best Wishes,</div><div class=\"preview-signature-name\">Ms. S. Radha Chauhan</div><div class=\"preview-signature-title\">Chairperson</div></div></div>', '', 'full_html'),
('basic', 0, 10, 10, 'en', 0, '<div class=\"social-section-enhanced py-5\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row\"><div class=\"col-12\"><h2 class=\"social-section-title mb-4\">Follow Us</h2><div class=\"social-icons-enhanced\"><a class=\"social-icon-btn\" href=\"https://twitter.com/CBC_MK\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-x-twitter\"></i> <span>Twitter</span> </a><a class=\"social-icon-btn\" href=\"https://www.linkedin.com/company/capacity-building-commission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-linkedin\"></i> <span>LinkedIn</span> </a><a class=\"social-icon-btn\" href=\"https://www.instagram.com/capacitybuildingcommission/\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-instagram\"></i> <span>Instagram</span> </a><a class=\"social-icon-btn\" href=\"https://www.facebook.com/capacitybuildingcommission\" target=\"_blank\" rel=\"noopener noreferrer\"><i class=\"fab fa-facebook\"></i> <span>Facebook</span>&nbsp;</a></div></div></div></div></div></div>', '', 'full_html');
