('basic', 0, 1, 1, 'en', 0, '<h2 class=\"mission-title\">About <span class=\"accent-text\">Us</span></h2><p class=\"mission-text\">Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.</p>', '', 'full_html'),
('basic', 0, 2, 2, 'en', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img class=\"modi-image\" src=\"http://localhost/cbc/themes/cbc/img/pm_modi.jpg\" alt=\"Prime Minister Narendra Modi\" width=\"934\" height=\"452\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">\"National Programme for Civil Services Capacity Building will radically improve the Human Resource Management practices in the Government through state of the art infrastructure to augment the capacity of Civil Servants.\"</p><p class=\"modi-message-attribution\">- Hon\'ble Prime Minister</p></div></div>', '', 'full_html'),
('basic', 0, 3, 3, 'en', 0, '<div class=\"jitender-card\"><div class=\"jitender-content-wrapper\"><div class=\"jitender-section\"><div class=\"jitender-image-wrapper\"><img class=\"jitender-image\" src=\"http://localhost/cbc/themes/cbc/img/Jitendra_Singh.jpg\" alt=\"Dr. Jitendra Singh\" width=\"889\" height=\"675\"></div></div><div class=\"jitender-message-section\"><p class=\"mission-text jitender-message-text\">\"National Standards for Civil Service Training Institutes 2.0 is not just a compliance tool—it is a transformative step toward institutional excellence.\"</p><div class=\"jitender-name-badge\"><p>Dr. Jitendra Singh</p><p class=\"f-6\">Hon\'ble Minister of State</p></div></div></div></div>', '', 'full_html'),
('basic', 0, 4, 4, 'en', 0, '<p><i class=\"fas fa-map-marker-alt\"></i> 7th Floor, NDCC-II Building, New Delhi, India</p><p><i class=\"fas fa-phone-alt\"></i> +91 11 2309 3200</p><p><i class=\"fas fa-envelope\"></i> info@cbc.gov.in</p>', '', 'full_html'),
('basic', 0, 5, 5, 'en', 0, '<h2>Capacity Building Commission</h2><p>Strengthening governance and empowering civil services through innovation, training, and collaborative leadership under Mission Karmayogi.</p><div class=\"social-icons\"><a href=\"#\"><i class=\"fab fa-x-twitter\"></i></a> <a href=\"#\"><i class=\"fab fa-linkedin\"></i></a> <a href=\"#\"><i class=\"fab fa-instagram\"></i></a> <a href=\"#\"><i class=\"fab fa-facebook\"></i></a></div>', '', 'full_html'),
