INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 4, 4, 'en', 0, '<div class=\"modi-content-wrapper\"><!-- Modi Section --><div class=\"modi-section\"><div class=\"modi-image-wrapper\"><img class=\"modi-image\" src=\"{{ base_path }}themes/cbc/img/pm_modi.jpg\" alt=\"Prime Minister Narendra Modi\"></div></div><div class=\"modi-message-section\"><p class=\"mission-text modi-message-text\">\"National Programme for Civil Services Capacity Building will radically improve the Human Resource Management practices in the Government through state of the art infrastructure to augment the capacity of Civil Servants.\"</p><p class=\"modi-message-attribution\">- Hon\'ble Prime Minister</p></div></div>', '', 'full_html'),
('our_collaboration_matters', 1, 24, 49, 'en', 0, '<p>Congratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'full_html'),
('our_collaboration_matters', 1, 24, 54, 'en', 0, '<p>Congratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'full_html'),
('our_collaboration_matters', 1, 25, 50, 'en', 0, '<p>OCongratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'full_html'),
('our_collaboration_matters', 1, 25, 53, 'en', 0, '<p>Valedictory of 100 Hrs to Mission Karmayogi for Lakshadweep Police</p>', '', 'full_html'),
('our_collaboration_matters', 1, 26, 51, 'en', 0, '<p>A shared culture of learning &amp; #SevaBhav is taking root across depts-breaking silos, making service more humane, more responsive &amp; more reliable. Governance is strengthening itself from within as we move toward a #ViksitBharat2047</p>', '', 'full_html'),
('page', 0, 32, 68, 'en', 0, '<div class=\"mission-karmayogi-header mb-4 py-4 px-3 rounded text-center\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);border-radius:5.25px !important;box-shadow:rgba(0, 75, 136, 0.1) 0px 4px 15px;box-sizing:border-box;color:rgb(33, 37, 41);cursor:pointer;display:block;font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:1.5rem !important;max-width:100%;orphans:2;overflow-wrap:break-word;padding:1.5rem 1rem !important;text-align:center !important;text-decoration:none;text-indent:0px;text-transform:none;transition:0.3s;white-space:normal;widows:2;width:1010px;word-spacing:0px;\"><h2 class=\"mb-0 fw-bold\" style=\"box-sizing:border-box;color:rgb(255, 255, 255);font-size:1.4rem !important;font-weight:700 !important;line-height:1.2;margin-bottom:0px !important;margin-top:0px;text-decoration:none;\">Mission Karmyogi</h2></div><div class=\"intro-content mb-3\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:1rem !important;max-width:100%;orphans:2;overflow-wrap:break-word;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><p class=\"text-muted\" style=\"--bs-text-opacity:1;box-sizing:border-box;color:rgba(33, 37, 41, 0.75) !important;font-size:0.9rem !important;margin-bottom:1rem;margin-top:0px;max-width:100%;overflow-wrap:break-word;text-align:justify !important;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">National Programme for Civil Services Capacity Building (NPCSCB) – Mission Karmayogi</strong> was launched in September 2020.</p></div><div class=\"mission-karmayogi-highlight mb-5 p-4 rounded\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);border-left:5px solid rgb(255, 193, 7);border-radius:5.25px !important;box-shadow:rgba(0, 75, 136, 0.1) 0px 4px 15px;box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:3rem !important;max-width:100%;orphans:2;overflow-wrap:break-word;padding:1.5rem !important;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;transition:0.3s;white-space:normal;widows:2;word-spacing:0px;\"><div class=\"row align-items-center\" style=\"--bs-gutter-x:1.5rem;--bs-gutter-y:0;align-items:center !important;box-sizing:border-box;display:flex;flex-wrap:wrap;font-size:inherit;margin-left:-15px;margin-right:-15px;margin-top:0px;max-width:100%;overflow-wrap:break-word;\"><div class=\"col-md-12\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-top:0px;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;width:963.333px;\" mb-4=\"\"><p class=\"mb-2\" style=\"box-sizing:border-box;font-size:0.9rem !important;margin-bottom:0.5rem !important;margin-top:0px;max-width:100%;overflow-wrap:break-word;text-align:justify !important;\"><strong style=\"box-sizing:border-box;font-weight:bolder;\">\"Mission Karmayogi\"</strong> – aims to create a competent civil service rooted in Indian ethos, with a shared understanding of India\'s priorities, working in harmonization for effective and efficient public service delivery.</p><p class=\"mb-0\" style=\"box-sizing:border-box;font-size:0.9rem !important;margin-bottom:0px !important;margin-top:0px;max-width:100%;overflow-wrap:break-word;text-align:justify !important;\">Envisioned as one of the largest capacity building initiatives in Government anywhere in the world, Mission Karmayogi aims to transform approximately <strong style=\"box-sizing:border-box;font-weight:bolder;\">1.5 crore government officials</strong> across the Centre, the States, and the local bodies.</p></div><div class=\"col-md-12 text-center mb-3 mb-md-0 mt-4\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-bottom:0px !important;margin-top:1.5rem !important;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;text-align:center !important;width:963.333px;\"><div class=\"institutional-framework-flowchart\" style=\"box-sizing:border-box;font-size:inherit;margin-top:0px;max-width:100%;overflow-wrap:break-word;\"><div class=\"framework-header\" style=\"background-color:rgb(0, 99, 174);border-radius:8px 8px 0px 0px;box-sizing:border-box;font-size:inherit;margin-bottom:0px;max-width:100%;overflow-wrap:break-word;padding:10px 15px;\"><h4 class=\"framework-title\" style=\"box-sizing:border-box;color:rgb(255, 255, 255);font-size:1.1rem !important;line-height:1.3;margin:0px;text-align:center;\"><strong>Mission Karmayogi – Institutional Framework</strong></h4></div><div class=\"framework-content\" style=\"background-color:rgb(255, 255, 255);border-bottom:2px solid rgb(233, 236, 239);border-image:initial;border-left:2px solid rgb(233, 236, 239);border-radius:0px 0px 8px 8px;border-right:2px solid rgb(233, 236, 239);border-top-style:none;box-sizing:border-box;font-size:inherit;max-width:100%;overflow-wrap:break-word;padding:18px 12px;\"><div class=\"row g-3\" style=\"--bs-gutter-x:1rem;--bs-gutter-y:1rem;box-sizing:border-box;display:flex;flex-wrap:wrap;font-size:inherit;margin-left:-15px;margin-right:-15px;margin-top:-14px;max-width:100%;overflow-wrap:break-word;\"><div class=\"col-6\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-top:14px;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;width:452.667px;\"><div class=\"framework-box high-contrast-border cbc-box\" style=\"background-color:rgb(255, 224, 178);border-radius:8px;border:2px solid rgb(255, 152, 0);box-shadow:rgba(0, 0, 0, 0.05) 0px 2px 6px;box-sizing:border-box;font-size:inherit;height:180.24px;max-width:100%;overflow-wrap:break-word;padding:18px 12px;text-align:center;transition:0.3s;\"><div class=\"framework-logo cbc-logo\" style=\"align-items:center;box-sizing:border-box;display:flex;font-size:inherit;justify-content:center;margin-bottom:15px;max-width:100%;overflow-wrap:break-word;\"><img class=\"framework-logo-img\" style=\"box-sizing:border-box;max-height:80px;max-width:80px;object-fit:contain;vertical-align:middle;\" src=\"http://localhost/cbc-website/img/cbc_logo.png\" alt=\"CBC Logo\" width=\"NaN\" height=\"NaN\"></div><h5 class=\"framework-box-title\" style=\"box-sizing:border-box;color:rgb(27, 31, 35);font-size:1rem !important;line-height:1.4;margin-bottom:8px;margin-top:0px;\"><strong>Capacity Building Commission</strong></h5></div></div><div class=\"col-6\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-top:14px;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;width:452.667px;\"><div class=\"framework-box high-contrast-border karmayogi-box\" style=\"background-color:rgb(255, 249, 196);border-radius:8px;border:2px solid rgb(251, 192, 45);box-shadow:rgba(0, 0, 0, 0.05) 0px 2px 6px;box-sizing:border-box;font-size:inherit;height:180.24px;max-width:100%;overflow-wrap:break-word;padding:18px 12px;text-align:center;transition:0.3s;\"><div class=\"framework-logo karmayogi-logo\" style=\"align-items:center;box-sizing:border-box;display:flex;font-size:inherit;justify-content:center;margin-bottom:15px;max-width:100%;overflow-wrap:break-word;\"><a class=\"framework-box-link\" style=\"box-sizing:border-box;color:rgb(13, 110, 253);display:block;font-size:inherit;height:180.24px;max-width:100%;overflow-wrap:break-word;text-decoration:none;\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\"><img class=\"framework-logo-img\" style=\"box-sizing:border-box;max-height:80px;max-width:80px;object-fit:contain;vertical-align:middle;\" src=\"http://localhost/cbc-website/img/igot_karmyogi_logo.png\" alt=\"iGOT Karmayogi Logo\" width=\"NaN\" height=\"NaN\"></a></div><h5 class=\"framework-box-title\" style=\"box-sizing:border-box;color:rgb(27, 31, 35);font-size:1rem !important;line-height:1.4;margin-bottom:8px;margin-top:0px;\"><a class=\"framework-box-link\" style=\"box-sizing:border-box;color:rgb(13, 110, 253);display:block;font-size:inherit;height:180.24px;max-width:100%;overflow-wrap:break-word;text-decoration:none;\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\"><strong>Karmayogi Bharat</strong></a></h5><p class=\"framework-box-subtitle\" style=\"box-sizing:border-box;color:rgb(108, 117, 125);font-size:0.8rem;line-height:1.4;margin:0px;max-width:100%;overflow-wrap:break-word;text-align:justify !important;\"><a class=\"framework-box-link\" style=\"box-sizing:border-box;color:rgb(13, 110, 253);display:block;font-size:inherit;height:180.24px;max-width:100%;overflow-wrap:break-word;text-decoration:none;\" href=\"https://igotkarmayogi.gov.in/#/\" target=\"_blank\">(SPV - 100% govt. owned online learning platform - iGOT Karmayogi)</a></p></div></div></div></div></div></div></div></div><div class=\"about-cbc-core mb-5\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;margin-bottom:3rem !important;max-width:100%;orphans:2;overflow-wrap:break-word;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\"><h2 class=\"mb-4 fw-bold\" style=\"box-sizing:border-box;color:rgb(33, 37, 41);font-size:1.4rem !important;font-weight:700 !important;line-height:1.2;margin-bottom:1.5rem !important;margin-top:0px;\">About Capacity Building Commission</h2><div class=\"row\" style=\"--bs-gutter-x:1.5rem;--bs-gutter-y:0;box-sizing:border-box;display:flex;flex-wrap:wrap;font-size:inherit;margin-left:-15px;margin-right:-15px;margin-top:0px;max-width:100%;overflow-wrap:break-word;\"><div class=\"col-lg-12\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-top:0px;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;width:1010px;\"><div class=\"cbc-intro-card p-4 mb-4 rounded\" style=\"background-color:rgb(255, 255, 255);border-radius:5.25px !important;border:2px solid rgb(233, 236, 239);box-shadow:rgba(0, 75, 136, 0.1) 0px 4px 15px;box-sizing:border-box;font-size:inherit;margin-bottom:1.5rem !important;max-width:100%;overflow-wrap:break-word;padding:1.5rem !important;transition:0.3s;\"><div class=\"row align-items-center\" style=\"--bs-gutter-x:1.5rem;--bs-gutter-y:0;align-items:center !important;box-sizing:border-box;display:flex;flex-wrap:wrap;font-size:inherit;margin-left:-15px;margin-right:-15px;margin-top:0px;max-width:100%;overflow-wrap:break-word;\"><div class=\"col-md-12\" style=\"box-sizing:border-box;flex:0 0 auto;font-size:inherit;margin-top:0px;max-width:100%;overflow-wrap:break-word;padding-left:15px;padding-right:15px;width:934px;\"><p class=\"mb-3\" style=\"box-sizing:border-box;font-size:0.9rem !important;margin-bottom:1rem !important;margin-top:0px;max-width:100%;overflow-wrap:break-word;text-align:justify !important;\">Capacity Building Commission (CBC), is the executive body of the Mission Karmayogi framework, to drive civil service reforms through capacity building and competency-based learning. It works to strengthen the human resource foundations of the government by focusing on developing individual and institutional capacities, promoting citizen-centric governance, future readiness, and fostering a culture of lifelong learning across all levels of public administration. The Commission designs frameworks, sets standards, and encourages collaboration to make governance more transparent, accountable, citizen-centric, and future-ready.</p></div></div></div></div></div></div><div class=\"vision-mission-section\" style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);box-sizing:border-box;color:rgb(33, 37, 41);font-family:system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, &quot;Helvetica Neue&quot;, &quot;Noto Sans&quot;, &quot;Liberation Sans&quot;, Arial, sans-serif, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;max-width:100%;orphans:2;overflow-wrap:break-word;text-align:start;text-decoration-color:initial;text-decoratio