INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 64, 104, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The National Training Conclave (NTC) 2023, inaugurated by the Hon\'ble Prime Minister on <strong style=\"color:#0063ae;\">11th June 2023</strong>, was envisioned by the Capacity Building Commission (CBC) as a landmark initiative to strengthen India\'s civil service training ecosystem. It aimed to bring together over <strong style=\"color:#0063ae;\">1000+ Central and State Civil Service Training Institutions (CSTIs)</strong>, senior government officials, academicians, and knowledge partners onto a common platform for collaboration, knowledge exchange, and institutional strengthening.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">The core vision of the NTC was to create a <strong style=\"color:#0063ae;\">future-ready civil service</strong> capable of driving India\'s transformation toward <strong style=\"color:#0063ae;\">Viksit Bharat @2047</strong>. The Conclave emphasized the need to move from fragmented training approaches to a <strong style=\"color:#0063ae;\">\"whole-of-government\"</strong> and <strong style=\"color:#0063ae;\">\"whole-of-system\"</strong> learning ecosystem, where capacity building becomes continuous, competency-driven, and technology-enabled.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">Through its <strong style=\"color:#0063ae;\">8 thematic breakout sessions</strong>, NTC focused on strengthening the foundations of training institutions in key areas—training needs assessment, knowledge sharing, impact evaluation, strategic resource planning, faculty development, phygital transformation, governance challenges, and competency-based capacity building. The discussions were designed to help CSTIs identify institution-level and policy-level interventions to enhance training quality and impact.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">Another major vision element was to standardize quality and institutional excellence across CSTIs through the <strong style=\"color:#0063ae;\">National Standards for Civil Service Training Institutions (NSCSTI)</strong>, which were launched and awarded during the conclave. This framework aims to make India\'s training institutions globally benchmarked and capable of nurturing ethical, competent, and citizen-centric civil servants.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">NTC also sought to foster innovation and collaboration through technology lounges, including the <strong style=\"color:#0063ae;\">iGOT Karmayogi Lounge</strong> and <strong style=\"color:#0063ae;\">Emerging Tech Lounge</strong>, showcasing digital tools and immersive learning technologies.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">In essence, the National Training Conclave envisioned a transformed, interconnected, and adaptive training ecosystem—one that continuously upgrades the skills, mindset, and leadership of public servants, institutionalizes best practices, and ensures that training translates into tangible governance outcomes for citizens.</p></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;\"><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Facilitate collaboration and networking among CSTIs to share best practices and innovations.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Introduce and operationalize the National Standards for Civil Service Training Institutions (NSCSTI) for quality benchmarking.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Identify actionable strategies from the 8 breakout sessions to improve institutional and training performance.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Strengthen awareness and adoption of digital tools, especially the iGOT Karmayogi platform, for phygital learning.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Institutionalize the National Training Conclave as a recurring platform for knowledge exchange and reform.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Create a world-class training ecosystem aligned with the Mission Karmayogi vision of a future-ready civil service.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Promote competency-based, technology-driven, and citizen-centric training models across all government institutions.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Achieve nationwide NSCSTI accreditation and build CSTIs\' capacity on the eight pillars of excellence.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Drive continuous learning, collaboration, and behavioural transformation across government systems.</li></ul></div></div></div></div></section><!-- Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3\" style=\"color:#0063ae;\"></i>Concept Note</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Concept Overview</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The National Training Conclave (NTC) 2023, organized by the Capacity Building Commission (CBC) under Mission Karmayogi, was conceptualized as a nationwide platform to strengthen collaboration among Central and State Training Institutions (CSTIs) and align capacity-building efforts with the vision of <strong style=\"color:#0063ae;\">Viksit Bharat @2047</strong>. The Conclave aimed to transform the training ecosystem by fostering synergy, innovation, and standardization across institutions.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">It brought together more than <strong style=\"color:#0063ae;\">1000 training institutions</strong> and senior government officials to deliberate on improving training quality through competency-based design, technology integration, impact assessment, and governance reforms. A major focus was the launch and adoption of the <strong style=\"color:#0063ae;\">National Standards for Civil Service Training Institutions (NSCSTI)</strong>—a framework to benchmark quality and institutional excellence across CSTIs.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">The Conclave\'s eight thematic breakout sessions provided actionable pathways for reform, emphasizing digital transformation through iGOT Karmayogi, data-driven governance, and institutional collaboration.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">In essence, the NTC was envisioned as a catalyst for professionalizing public service training, institutionalizing continuous learning, and building a future-ready, citizen-centric civil service through shared learning, technology, and capacity enhancement.</p></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>Pre-event</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Conceptualized by CBC; engagement with 1000+ CSTIs nationwide.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>11 June 2023</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Launch by Hon\'ble Prime Minister; unveiling of NSCSTI Dashboard and accreditation to NADT, SVPNPA, and NICF.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>Opening Session</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Address by Hon\'ble MoS Dr. Jitendra Singh; launch of NSCSTI Copyright Certificate; vision presented by CBC Chairperson.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Eight Breakout Sessions</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Discussions on training needs, knowledge sharing, impact assessment, resource planning, faculty capacity, phygital transformation, governance, and competencies.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Lounges</strong></div><div style=\"color:#002b5b;line-height:1.7;\">NSCSTI, iGOT, Emerging Technologies, and Interview lounges established for engagement and demonstrations.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>Closing Ceremony</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Addresses by Dr. P.K. Mishra and MoS Dr. Jitendra Singh; recommendations consolidated.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>Post-event Strategy</strong></div><div style=\"color:#002b5b;line-height:1.7;\">CBC to institutionalize NTC, implement panel recommendations, and expand NSCSTI accreditation.</div></div></div></div></div></div></div></div></section><!-- Key Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-flag-fill me-3\" style=\"color:#0063ae;\"></i>Key Milestones</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-rocket-takeoff-fill\" style=\"color:#0063ae;\"></i></p><h4>Inauguration by Hon\'ble Prime Minister (11th June 2023)</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Launch of the <strong style=\"color:#0063ae;\">National Standards for Civil Service Training Institutions (NSCSTI)</strong> framework.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Unveiling of the <strong style=\"color:#0063ae;\">PM Dashboard on NSCSTI</strong>.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Distribution of NSCSTI Accreditation Certificates to three Central Training Institutions — <strong style=\"color:#0063ae;\">NADT, SVPNPA, and NICF</strong>.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> PM\'s address highlighting the vision of Future-Ready Civil Servants and <strong style=\"color:#0063ae;\">Viksit Bharat @2047</strong>.</li></ul></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-person-badge-fill\" style=\"color:#28a745;\"></i></p><h4>Opening Session (Led by Hon\'ble MoS Dr. Jitendra Singh)</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Distribution of NSCSTI Accreditation Certificates to <strong style=\"color:#28a745;\">seven additional CSTIs</strong>.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Presentation of CBC\'s vision for CSTIs by Chairperson, CBC.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Launch of <strong style=\"color:#28a745;\">Copyright Certificate for NSCSTI</strong>.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Presentations by CBC Members and CEO, Karmayogi Bharat, on Faculty Development, iGOT platform, and NSCSTI framework.</li></ul></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-chat-square-dots-fill\" style=\"color:#ffa500;\"></i></p><h4>Breakout Sessions (8 Thematic Panel Discussions)</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><p style=\"color:#002b5b;margin-bottom:15px;\"><strong>Deliberations on key capacity-building themes:</strong></p><div class=\"row g-3\"><div class=\"col-md-6\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-1-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Training Needs &amp; Course Design</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-2-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Knowledge Sharing</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-3-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Training Impact Assessment</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-4-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Strategic Resource Planning</li></ul></div><div class=\"col-md-6\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-5-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Faculty Capacity Enhancement</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-6-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Phygital Transformation</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-7-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Overcoming Governance Challenges</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-8-circle-fill\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Competencies for Civil Service Officials</li></ul></div></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #dc3545;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#dc3545;\"></i></p><h4>Lounge Installations</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#dc3545;left:0;position:absolute;\"></i> <strong style=\"color:#dc3545;\">NSCSTI Lounge</strong> – for accreditation guidance and process handholding.</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#dc3545;left:0;position:absolute;\"></i> <strong style=\"color:#dc3545;\">iGOT Lounge</strong> – for platform familiarization and digital course creation.</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#dc3545;left:0;position:absolute;\"></i> <strong style=\"color:#dc3545;\">Emerging Technology Lounge</strong> – showcasing AR/VR and AI-based learning tools.</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#dc3545;left:0;position:absolute;\"></i> <strong style=\"color:#dc3545;\">Interview Lounge</strong> – capturing stakeholder insights and experiences.</li></ul></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #6c757d;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clipboard-check-fill\" style=\"color:#6c757d;\"></i></p><h4>Closing Ceremony</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#6c757d;left:0;position:absolute;\"></i> Presentation of key recommendations from breakout sessions before Hon\'ble MoS and Principal Secretary to PM.</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#6c757d;left:0;position:absolute;\"></i> Address by <strong style=\"color:#6c757d;\">Dr. P.K. Mishra</strong> emphasizing holistic training and technological adaptability.</li><li style=\"margin-bottom:8px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#6c757d;left:0;position:absolute;\"></i> Closing remarks by <strong style=\"color:#6c757d;\">Dr. Jitendra Singh</strong> highlighting faculty development, behavioural training, and PPP models.</li></ul></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-arrow-right-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Post-Conclave Strategy (Way Forward)</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Integration of panel recommendations into CBC\'s policy and institutional initiatives.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Expansion of NSCSTI accreditation and capacity-building programs.</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> <strong style=\"color:#0063ae;\">Institutionalisation of NTC</strong> as a recurring platform for collaboration, learning, and innovation in civil services training.</li></ul></div></div></div></div></section><!-- Impact Metrics Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\" style=\"color:#28a745;\"></i>Impact Metrics (Outcomes achieved, measurable indicators)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#0063ae;\"></i></p><h4>Major Outcomes</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The Conclave brought together more than <strong style=\"color:#0063ae;\">1,500–1,900 representatives</strong> from Civil Service Training Institutes (CSTIs), including central training institutes, state administrative training institutes, zonal/regional training institutes, and research institutes.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> <strong style=\"color:#0063ae;\">Eight thematic panel discussions</strong> were organised covering key areas: training-needs identification, linking training to course design, faculty development, training-impact assessment, content digitisation, strategic resource planning, capacity enhancement, and evolving in a \"phygital\" (physical + digital) world of capacity building.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> A strong emphasis on breaking down vertical and horizontal silos, encouraging a <strong style=\"color:#0063ae;\">\"whole of government\"</strong> mindset among civil servants, and promoting citizen-participation (\"Jan Bhagidari\").</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Recognition that training should no longer be seen as a \"punishment posting\" but as a key component of career development and governance effectiveness.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> The importance of digital platforms such as the <strong style=\"color:#0063ae;\">iGOT Karmayogi platform</strong> – which had already crossed a registration of <strong style=\"color:#28a745;\">10 lakh (1 million) users</strong> – was highlighted as enabling \"anytime, anywhere, any device\" learning for government personnel.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Recommendations from the Conclave are compiled in a report which outlines actionable strategies for CSTIs, including improved training-needs assessment, linking course-design to competencies, and moving toward shared resources and standardisation of training institutions (National Standards for Civil Service Training Institutions – NSCSTI).</li></ul></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#28a745;\"></i></p><h4>Broader Implications</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> <strong style=\"color:#28a745;\">Strengthening training infrastructure:</strong> The Conclave is a push towards modernising and upgrading training institutions for civil servants across India, aligning them with future-ready skills and governance needs.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> <strong style=\"color:#28a745;\">Institutionalising peer-learning and collaboration:</strong> With multiple training institutes, state/local government officials, and private-sector experts participating, the event sets up a platform for cross-learning and sharing best practices.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> <strong style=\"color:#28a745;\">Embedding a service-orientation mindset:</strong> By emphasising \"ownership\", \"service to the citizen\", and moving beyond hierarchy, the Conclave signals a shift in how government training is conceptualised — not just technical skills, but mindset, attitude, and governance culture.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> <strong style=\"color:#28a745;\">Digital-first and competency-based training:</strong> The discussion around digitisation, online platforms, training-impact assessments, and linking-competencies indicate a shift from traditional classroom-centric training to blended, technology-enabled, outcomes-oriented capacity building.</li></ul></div></div></div></div></div></div></section><!-- Full Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-earmark-text-fill me-3\" style=\"color:#0063ae;\"></i>Conseptual Framework</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-file-earmark-pdf-fill\" style=\"color:#0063ae;\"></i></p><h4>Document</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\">Complete concept note for National Training Conclave 2023 is available below.</p><div style=\"align-items:center;background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;cursor:pointer;display:flex;gap:15px;padding:20px;transition:all 0.3s ease;\" onmouseover=\"this.style.backgroundColor=&apos;rgba(0, 99, 174, 0.15)&apos;; this.style.transform=&apos;translateX(5px)&apos;\" onmouseout=\"this.style.backgroundColor=&apos;rgba(0, 99, 174, 0.1)&apos;; this.style.transform=&apos;translateX(0)&apos;\"><p><i class=\"bi bi-file-earmark-text-fill\" style=\"color:#0063ae;font-size:2.5rem;\"></i></p><div style=\"flex:1;\"><p style=\"color:#002b5b;font-size:1.1rem;margin:0;\"><strong>National Training Conclave 2023 - Full Concept Note</strong></p><p style=\"color:#6c757d;font-size:0.9rem;margin:5px 0 0 0;\">Complete concept document for NTC 2023</p></div><p><a style=\"color:#0063ae;font-size:1.5rem;text-decoration:none;\" href=\"#\" title=\"View/Download Document\"><i class=\"bi bi-download\"></i>&nbsp;</a></p></div></div></div></div></section><!-- Relevant Data Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-folder-fill me-3\" style=\"color:#0063ae;\"></i>Relevant Data</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-file-earmark-pdf-fill\" style=\"color:#dc3545;\"></i></p><h4>Reports &amp; Documents</h4></div><div style=\"margin-top:20px;\"><div style=\"align-items:center;background-color:rgba(220, 53, 69, 0.1);border-left:4px solid #dc3545;border-radius:8px;cursor:pointer;display:flex;gap:15px;padding:20px;transition:all 0.3s ease;\" onmouseover=\"this.style.backgroundColor=&apos;rgba(220, 53, 69, 0.15)&apos;; this.style.transform=&apos;translateX(5px)&apos;\" onmouseout=\"this.style.backgroundColor=&apos;rgba(220, 53, 69, 0.1)&apos;; this.style.transform=&apos;translateX(0)&apos;\"><p><i class=\"bi bi-file-earmark-pdf-fill\" style=\"color:#dc3545;font-size:2.5rem;\"></i></p><div style=\"flex:1;\"><p style=\"color:#002b5b;font-size:1.1rem;margin:0;\"><strong>NTC Report.pdf</strong></p><p style=\"color:#6c757d;font-size:0.9rem;margin:5px 0 0 0;\">National Training Conclave 2023 Report</p></div><p><a style=\"color:#dc3545;font-size:1.5rem;text-decoration:none;\" href=\"#\" title=\"View/Download Report\"><i class=\"bi bi-download\"></i>&nbsp;</a></p></div></div></div></div></div></section><!-- Connection to NLW Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-link-45deg me-3\" style=\"color:#0063ae;\"></i>Connection with National Learning Week</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;\"><div class=\"karmayogi-quote-icon\" style=\"color:#0063ae;\"><i class=\"bi bi-diagram-3-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;\">The National Training Conclave (NTC) and National Learning Week (NLW) are <strong style=\"color:#0063ae;\">complementary initiatives</strong> under Mission Karmayogi, both working toward the shared vision of transforming India\'s civil service training ecosystem. While the <strong style=\"color:#0063ae;\">National Training Conclave 2023</strong> laid the foundation by bringing together training institutions and establishing standards (NSCSTI), the <strong style=\"color:#0063ae;\">National Learning Week 2024</strong> operationalized these frameworks by engaging individual civil servants in competency-based learning.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">NTC focused on <strong style=\"color:#0063ae;\">institutional strengthening</strong>—creating standards, building capacity of training institutions, and fostering collaboration among CSTIs. NLW, on the other hand, focuses on <strong style=\"color:#0063ae;\">individual and organizational learning culture</strong>—encouraging civil servants to take ownership of their learning journeys and embedding continuous development as a professional norm.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;line-height:1.8;margin-top:15px;\">Together, these initiatives create a <strong style=\"color:#0063ae;\">comprehensive ecosystem</strong> where training institutions are strengthened (NTC) and learners are motivated and enabled (NLW), ensuring that capacity building becomes both institutionalized and personalized, leading to a future-ready civil service aligned with Viksit Bharat 2047.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-milestone-card high-contrast-border\" style=\"border:3px solid #0063ae;\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">National Training Conclave</div><div class=\"karmayogi-milestone-label\" style=\"margin-bottom:15px;\">Institutional strengthening and standardization</div><p><span class=\"btn\" style=\"background-color:#0063ae;border-style:none;color:white;cursor:default;font-size:0.9rem;padding:8px 20px;\">Current Page</span></p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-milestone-card high-contrast-border\" style=\"border:3px solid #28a745;\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-mortarboard-fill\"></i></div><div class=\"karmayogi-milestone-title\">National Learning Week</div><div class=\"karmayogi-milestone-label\" style=\"margin-bottom:15px;\">Individual learning culture and continuous development</div><p><a class=\"btn btn-primary\" style=\"background-color:#28a745;border-style:none;font-size:0.9rem;padding:8px 20px;\" href=\"#/initiatives/national-learning-week\">Learn More</a></p></div></div></div></div></div></section><!-- Media Assets Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-image-fill me-3\" style=\"color:#0063ae;\"></i>Media Assets</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-folder-fill\" style=\"color:#0063ae;\"></i></p><h4>Resources</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">All media assets and resources for the National Training Conclave 2023 are hosted on the dedicated microsite:</p><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:5px solid #0063ae;border-radius:10px;margin-top:20px;padding:20px;\"><p><a style=\"align-items:center;color:#0063ae;display:inline-flex;font-size:1.1rem;gap:10px;text-decoration:none;\" href=\"https://cbc.gov.in/cbc-ntc2023/\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Visit NTC 2023 Microsite&nbsp;</strong></a></p><p style=\"color:#6c757d;font-size:0.95rem;margin-bottom:0;margin-top:10px;\">https://cbc.gov.in/cbc-ntc2023/</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 105, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"pages/initiatives/registration-guidelines-igot.html\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/important-documents.html\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/how-to-access-igot-video.html\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 107, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"pages/initiatives/registration-guidelines-igot.html\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/important-documents.html\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/how-to-access-igot-video.html\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 108, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"pages/initiatives/registration-guidelines-igot.html\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/important-documents.html\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/how-to-access-igot-video.html\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 111, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"pages/initiatives/registration-guidelines-igot.html\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/important-documents.html\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"pages/initiatives/how-to-access-igot-video.html\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 214, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 65, 215, 'en', 0, '<!-- Vision and In Focus Card Section Side by Side --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Vision Section --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title left-aligned\"><i class=\"bi bi-eye-fill me-3 icon-blue\"></i>Vision</h2><div class=\"karmayogi-quote-block\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\">This program aims to instill a deeper sense of <strong>Seva Bhaav</strong> (spirit of service) and <strong>Svadharma</strong> (duty aligned with personal purpose) among civil servants. Drawing from the Karmayogi Competency Framework, the program seeks to realign officers\' inner purpose with their public-facing roles, fostering values that enhance responsiveness, accountability, and service excellence.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div class=\"important-info-card\"><!-- Red Header Section --><div class=\"card-header\"><h4><i class=\"bi bi-exclamation-circle-fill\"></i> Important Information</h4></div><!-- Links Section --><div class=\"card-body\"><div class=\"important-info-links-wrapper\"><h5><a class=\"important-info-link\" href=\"/cbc/registration-guidelines-for-igot\"><i class=\"bi bi-file-earmark-text-fill\"></i> Registration Guidelines For iGOT</a></h5><h5><a class=\"important-info-link\" href=\"/cbc/important-documents\"><i class=\"bi bi-folder-fill\"></i> Important Documents</a></h5><h5><a class=\"important-info-link\" href=\"/cbc/how-access-igot-video\"><i class=\"bi bi-play-circle-fill\"></i> How To Access On iGOT - Video</a></h5></div></div></div></div></div></div></div></section><!-- Objective Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3 icon-dark-blue\"></i>Objective</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The primary objective of this intervention is to awaken <strong>Seva Bhav</strong>/ sense of service in central government employees which is critical to serve the citizens. This will lead to –</p><div class=\"row g-4 mt-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-green\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Improved Citizen Services</div><div class=\"karmayogi-milestone-label\">Enhanced quality and responsiveness in public service delivery</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-blue\"><i class=\"bi bi-diagram-3-fill\"></i></div><div class=\"karmayogi-milestone-title\">Better Collaboration</div><div class=\"karmayogi-milestone-label\">Improved responsiveness and collaboration across Government departments</div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon gradient-orange\"><i class=\"bi bi-heart-fill\"></i></div><div class=\"karmayogi-milestone-title\">Work Satisfaction</div><div class=\"karmayogi-milestone-label\">Enhancing one\'s work satisfaction and sense of fulfilment at work</div></div></div></div></div></div></section><!-- Program Content Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3 icon-blue\"></i>Program Content</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill icon-blue\"></i></p><h4>Program Overview</h4></div><p class=\"karmayogi-feature-desc\">In this program, participants will rediscover their inner power as Rashtriya Karmayogis. It is a <strong>1-day program</strong>, where participants will go through <strong>4 modules</strong>. These modules are not lecture-based but are highly interactive. They are designed to enable reflective discussions, experience sharing, teamwork to build answers together and building shared vision together.</p></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block blue-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge blue\">1</div><h4>Module 1</h4></div><p class=\"karmayogi-feature-desc\">We explore the qualities and behaviours of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block green-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge green\">2</div><h4>Module 2</h4></div><p class=\"karmayogi-feature-desc\">We explore the motivations and inner purpose of a Karmayogi.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block orange-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge orange\">3</div><h4>Module 3</h4></div><p class=\"karmayogi-feature-desc\">We learn how to integrate Seva-Bhav into every aspect of our work life.</p></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-feature-block red-gradient\"><div class=\"karmayogi-feature-header\"><div class=\"module-number-badge red\">4</div><h4>Module 4</h4></div><p class=\"karmayogi-feature-desc\">We understand our role in terms of national goals and serving all stakeholders better.</p></div></div></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events (Pilot / Phases)</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>November 2024 - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 1: Training of Master Trainers (Director/Deputy Secretary level) from Secretariats of all Central Ministries in Delhi. 10 batches conducted, training 278 Master Trainers from 85 Ministries and Departments.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>January - March 2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Master Trainers trained over 17,000 officials from their respective Ministries/Departments through the Train-the-Trainer (T3) cascade model.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>May 2025 onwards</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Phase 2: Immersive Workshop for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) at Sushma Swaraj Bhavan, New Delhi. Selection and training of Lead Trainers begins.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Ongoing</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Lead Trainers conduct 5-day intensive Train-the-Trainer program to develop 15-20,000 Karmayogi Coaches (Master Trainers). These coaches train approximately 7,00,000 Central Government employees across India.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Till 26.11.2025</strong></div><div style=\"color:#002b5b;line-height:1.7;\">More than 15,000 Karmayogi coaches have been trained in Phase 2. Over 7.50 lakh officials have been trained in one-day training program in Phase 2.</div></div></div></div></div></div></div></div></section><!-- End-of-Program Assessment Section --><section class=\"karmayogi-section-fullwidth karmayogi-alignment-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-clipboard-check-fill me-3\" style=\"color:#0063ae;\"></i>End-of-Program Assessment</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clock-fill\"></i></div><div class=\"karmayogi-milestone-title\">Module Duration</div><div class=\"karmayogi-milestone-label\">Each module is approximately <strong>1.5 hours</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">30 Learning Units</div><div class=\"karmayogi-milestone-label\">Collective Learning Units delivered via <strong>Pedgog App</strong></div></div></div><div class=\"col-md-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Samuhik Charchas</div><div class=\"karmayogi-milestone-label\">Group discussions in teams/ sections/ departments</div></div></div></div><p class=\"karmayogi-text-large mt-4\">The Program will be followed by <strong>30 Collective Learning Units</strong> that participants will receive one at a time on a Learning App (Pedgog), over the weeks that follow. These units will enable <strong>Samuhik Charchas</strong> to be held in the respective teams/ sections/ department over time.</p></div></div></section><!-- Implementation Strategy Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Implementation Strategy</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 mb-4\"><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-mortarboard-fill\" style=\"color:#0063ae;\"></i></p><h4>Train-the-Trainer (T3) Approach</h4></div><p class=\"karmayogi-feature-desc\">Rashtriya Karmayogi Jan Seva adopts a <strong>Train-the-Trainer (T3)</strong> approach. By equipping selected instructors with essential skills, the program empowers them to train others within their respective organizations.</p></div></div><div class=\"col-md-6\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#28a745;\"></i></p><h4>Cascade Model Benefits</h4></div><p class=\"karmayogi-feature-desc\">This cascade model not only provides trainers with valuable opportunities for professional development but also ensures that the training remains contextually relevant while maintaining consistency across the curriculum.</p></div></div></div><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-diagram-3\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\"><strong>The implementation of the Rashtriya Karmayogi Intervention will involve two phases:</strong></p></div><!-- Phase Overview Image --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"/cbc/sites/default/files/2025-12/phase.png\" alt=\"Phase I and Phase II Overview\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-4 mt-4\"><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #0063ae;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#0099ff;\">Phase I</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-building\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Delhi Secretariat</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#0063ae;\">10,000 Central Government employees</strong> in Secretariats of all Central Ministries in Delhi.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~15,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-building me-2\"></i>93 MDOs</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>Nov 2024 - Mar 2025</span></div></div></div><div class=\"col-md-6\"><div class=\"karmayogi-objective-block\" style=\"border-top:5px solid #28a745;\"><p><span class=\"karmayogi-objective-badge\" style=\"background-color:#20c997;\">Phase II</span></p><div style=\"align-items:center;display:flex;gap:15px;margin-bottom:20px;\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;width:60px;\"><i class=\"bi bi-globe\"></i></div><h3 class=\"karmayogi-objective-heading\" style=\"margin:0;\">Country-Wide</h3></div><p class=\"karmayogi-objective-text\">For around <strong style=\"color:#28a745;\">7,00,000 Central Government Employees</strong> across the country.</p><div class=\"karmayogi-badges-wrapper\" style=\"margin-top:20px;\"><span class=\"karmayogi-badge\"><i class=\"bi bi-people-fill me-2\"></i>Target: ~700,000 Personnel</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-geo-alt-fill me-2\"></i>Across India</span> <span class=\"karmayogi-badge\"><i class=\"bi bi-calendar-range me-2\"></i>May 2025 onwards</span></div></div></div></div></div></div></section><!-- Phase 1 Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-1-circle-fill me-3\" style=\"color:#0063ae;\"></i>Phase 1</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The first phase of this intervention is proposed to cover officers and officials of the rank of Director/Deputy Secretary/Under Secretary/Section Officers/Assistant Section Officers/Government Multi tasking Staff from Secretariats of Ministries/Departments of the Central Government in Delhi.</p><!-- Statistics Cards --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-check-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:2rem;\"><strong>10</strong></div><div class=\"karmayogi-milestone-label\">Batches Conducted</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:2rem;\"><strong>278</strong></div><div class=\"karmayogi-milestone-label\">Master Trainers</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:2rem;\"><strong>85</strong></div><div class=\"karmayogi-milestone-label\">Ministries &amp; Departments</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:2rem;\"><strong>17,000+</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;\"></i></p><h4>Implementation of Phase 1</h4></div><p class=\"karmayogi-feature-desc\">The Capacity Building Commission (CBC) successfully conducted <strong style=\"color:#0063ae;\">10 batches</strong> of the Rashtriya Karmayogi Large Scale Jan Seva Program training for Master Trainers in <strong style=\"color:#0063ae;\">January - March 2025</strong>. Under this large-scale behavioural training program, <strong style=\"color:#28a745;\">278 officers</strong> were trained as Master Trainers from <strong style=\"color:#ffa500;\">85 Ministries and Departments</strong> of Central Government. These trainers have trained over <strong style=\"color:#dc3545;\">17,000 officials</strong> from their respective Ministries/Department.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>The Train-the-Trainer (T3) Cascade Model</h4></div><p class=\"karmayogi-feature-desc\">The Master Trainer (Director/Deputy Secretary) or Karmayogi Coaches undergo a <strong style=\"color:#0063ae;\">3-day training programme</strong>. The Master Trainer (MT) after completion of a 3-day training programme trains <strong style=\"color:#28a745;\">100 other officials</strong> of their respective Ministry/Department in batches of <strong style=\"color:#ffa500;\">30 to 35</strong> (i.e at least 3 batches per Master Trainer). This is a <strong style=\"color:#dc3545;\">1-Day Program</strong> for each batch.</p><!-- Train-the-Trainer and Cascade Model Images Side by Side --><div class=\"row mt-4 mb-4 g-4\"><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/train-the-trainer .png\" alt=\"Train-the-Trainer Model\" width=\"NaN\" height=\"NaN\"></div></div><div class=\"col-md-6\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);height:100%;padding:25px;text-align:center;\"><img class=\"img-fluid\" style=\"border-radius:10px;max-width:100%;\" src=\"img/rastriya-karmyogi-assets/cascade-model.png\" alt=\"T3 Cascade Model\" width=\"NaN\" height=\"NaN\"></div></div></div><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Master Trainer Program</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>100</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Officials per MT</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>30-35</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Per Batch Size</div></div></div></div></div></div></div></section><!-- Phase 2 Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-2-circle-fill me-3\" style=\"color:#28a745;\"></i>Phase 2</h2><div class=\"karmayogi-content-wrapper\"><p class=\"karmayogi-text-large\">The Second phase of the Program takes this training to each office in the Government of India spread across the country. It aims to impart behavioural training to officers and officials of the rank of Director, Deputy Secretary, Under Secretary, Section Officers, Assistant Section Officers, Government Multi tasking Staff across government offices of India.</p><!-- Phase 2 Statistics --><div class=\"row g-4 mt-4\"><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-calendar-range-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#0063ae;font-size:1.8rem;\"><strong>5 Days</strong></div><div class=\"karmayogi-milestone-label\">Lead Trainer Program</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-person-badge-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#28a745;font-size:1.8rem;\"><strong>15,000+</strong></div><div class=\"karmayogi-milestone-label\">Karmayogi Coaches Trained</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#ffa500;font-size:1.8rem;\"><strong>20,000</strong></div><div class=\"karmayogi-milestone-label\">Target Coaches</div></div></div><div class=\"col-md-3 col-sm-6\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-trophy-fill\"></i></div><div class=\"karmayogi-milestone-title\" style=\"color:#dc3545;font-size:1.8rem;\"><strong>7.50 Lakh</strong></div><div class=\"karmayogi-milestone-label\">Officials Trained</div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-top:40px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;\"></i></p><h4>Immersive Workshop</h4></div><p class=\"karmayogi-feature-desc\">It began with an <strong style=\"color:#0063ae;\">Immersive Workshop</strong> for Senior Officers (Secretaries, Addl. Secretaries and Joint Secretaries) of the Government of India at <strong style=\"color:#0063ae;\">Sushma Swaraj Bhavan, New Delhi</strong>. It aimed to provide an overview to senior officials of the Rashtriya Karmayogi program, its core vision, structure, modules and seek leadership inputs on how to effectively implement phase II of the program.</p></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#28a745;\"></i></p><h4>Lead Trainers &amp; Karmayogi Coaches</h4></div><p class=\"karmayogi-feature-desc\">Subsequently, the second phase includes selection of <strong style=\"color:#0063ae;\">Lead Trainers</strong> from all Ministries/Departments, who undergo a <strong style=\"color:#0063ae;\">5-day intensive Train-the-Trainer program</strong> to prepare them to develop around <strong style=\"color:#28a745;\">15-20,000 Karmayogi Coaches</strong> (Master Trainers). These Lead trainers train around <strong style=\"color:#28a745;\">20,000 Karmayogi Coaches</strong> (Master Trainer) in a <strong style=\"color:#ffa500;\">3-day training program</strong>. Till <strong style=\"color:#dc3545;\">26.11.2025</strong> more than <strong style=\"color:#28a745;\">15,000 Karmayogi coaches</strong> have been trained in phase 2.</p><div class=\"row g-3 mt-4\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;\"><strong>5 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Lead Trainer Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;\"><strong>3 Days</strong></div><div style=\"color:#6c757d;margin-top:5px;\">Coach Training</div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:10px;padding:20px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;\"><strong>1 Day</strong></div><div style=\"color:#6c757d;margin-top:5px;\">End Participant Program</div></div></div></div></div><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-top:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#ffa500;\"></i></p><h4>Ground Delivery</h4></div><p class=\"karmayogi-feature-desc\">The ground delivery of the Program is to be managed by <strong style=\"color:#28a745;\">Karmayogi Coaches</strong> (Master Trainers) who conduct training for people specific to their MDOs in a <strong style=\"color:#ffa500;\">1-day training programme</strong>. The 1-day training program within all organizations of the Ministries/Departments of GoI would ensure that approximately <strong style=\"color:#dc3545;\">7,00,000 Central Government employees</strong> across India would have undertaken the 1-day training program.</p></div><!-- Phase 2 Flow Diagram --><div class=\"row mt-4 mb-4\"><div class=\"col-12\"><div style=\"background-color:#ffffff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);padding:25px;text-align:center;\"><h4 style=\"color:#002b5b;margin-bottom:20px;\"><strong>Phase 2 Implementation Flow</strong></h4><img class=\"img-fluid\" style=\"border-radius:10px;max-width:80%;\" src=\"img/rastriya-karmyogi-assets/summarizes-flow-diagram-Phase02.png\" alt=\"Phase 2 Flow Diagram\" width=\"NaN\" height=\"NaN\"></div></div></div><!-- Achievement Highlight --><div class=\"karmayogi-quote-block\" style=\"background-color:#d0e8ff;border-left:5px solid #28a745;margin-top:40px;overflow:hidden;position:relative;\"><div style=\"background-color:transparent;border-radius:50%;height:200px;position:absolute;right:-50px;top:-50px;width:200px;\">&nbsp;</div><div class=\"karmayogi-quote-icon\" style=\"color:#28a745;\"><i class=\"bi bi-trophy-fill\"></i></div><div style=\"position:relative;z-index:2;\"><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:1.5rem;font-style:normal;margin-bottom:10px;\"><strong style=\"color:#28a745;font-size:2rem;\">7.50 Lakh Officials</strong></p><p class=\"karmayogi-quote-text\" style=\"color:#6c757d;font-size:1.1rem;font-style:normal;font-weight:500;margin:0;\">have been trained till <strong style=\"color:#0063ae;\">26.11.2025</strong> in one day training in phase 2.<br>&nbsp;</p></div></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 67, 109, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 align-items-start\"><!-- Vision Content --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title\" style=\"font-size:1.8rem;margin-bottom:25px;text-align:left;\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;height:100%;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;\">The <strong style=\"color:#0063ae;\">Viksit Panchayat Initiative</strong> aims to equip Panchayat representatives and functionaries with the knowledge, skills, competencies, and tools required to strengthen grassroots governance. Anchored in the <strong style=\"color:#0063ae;\">73rd Constitutional Amendment Act of 1993</strong> and aligned with the vision of Mission Karmayogi, the initiative emphasizes capacity building as a pathway to enable Panchayats to move toward more participatory, accountable, and citizen-responsive governance.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;margin-top:12px;\">The initiative recognizes that effective Panchayati Raj Institutions (PRIs) are critical for improving the quality of life in rural communities. It focuses on building practical competencies identified through a role-based competency mapping exercise with Sarpanches and Gram Panchayat Secretaries, including <strong style=\"color:#28a745;\">leadership and facilitation</strong>, <strong style=\"color:#28a745;\">financial management</strong>, <strong style=\"color:#28a745;\">digital literacy</strong>, and <strong style=\"color:#28a745;\">participatory planning</strong>.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;margin-top:12px;\">A cornerstone of the initiative is the integration of <strong style=\"color:#0063ae;\">technology-enabled learning systems</strong>. Through an e-learning platform, capacity-building app, and AI-powered chatbot, Panchayat functionaries will have access to continuous, interactive, and context-specific learning support. Their integration with the <strong style=\"color:#0063ae;\">iGOT platform</strong> under Mission Karmayogi will ensure scalability, sustainability, and alignment with broader civil service capacity-building efforts.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;margin-top:12px;\">Ultimately, the vision is to create a demonstrable and scalable model of capacity building that empowers Panchayats to progressively evolve into more responsive, inclusive, and effective institutions of self-governance—contributing to the long-term aspiration of <strong style=\"color:#0063ae;\">Viksit Bharat @ 2047</strong>.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div style=\"background-color:#ffffff;border-radius:15px;border:3px solid #0063ae;box-shadow:0 6px 20px rgba(0, 0, 0, 0.15);display:flex;flex-direction:column;height:100%;overflow:hidden;\"><!-- Blue Header Section --><div style=\"background-color:#0063ae;flex-shrink:0;padding:15px 20px;\"><h4 style=\"align-items:center;color:#ffffff;display:flex;font-size:1.1rem;gap:10px;margin:0;\"><strong><i class=\"bi bi-info-circle-fill\" style=\"color:#ffffff;font-size:1.2rem;\"></i> Project Details</strong></h4></div><!-- Info Section --><div style=\"background-color:#ffffff;display:flex;flex-direction:column;flex:1;justify-content:space-between;padding:18px 20px;\"><div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-geo-alt-fill\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Pilot States</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">Andhra Pradesh, Assam, Gujarat, Odisha</div></div></div></div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Panchayats</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">15 Panchayats per state (60 total)</div></div></div></div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-calendar-range\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Duration</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">20 months (Pilot Project)</div></div></div></div><div style=\"margin-bottom:0;\"><div style=\"align-items:flex-start;display:flex;gap:8px;\"><p><i class=\"bi bi-people-fill\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Focus</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">Sarpanches, Ward Members, Secretaries, Gram Rozgar Sevaks</div></div></div></div></div></div></div></div></div></div></div></section><!-- Project Background Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-book-fill me-3\" style=\"color:#0063ae;\"></i>Project Background</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Context</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The <strong style=\"color:#0063ae;\">73rd Constitutional Amendment Act of 1993</strong> established Panchayati Raj Institutions (PRIs) as the cornerstone of local self-governance in India. For nearly three decades, continuous efforts by states have ensured the broad implementation of this system. Yet, there remains a pressing need to further strengthen citizen-centric governance at the grassroots—where everyday governance meets the people and directly influences their quality of life.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">The Capacity Building Commission, in collaboration with the Ministry of Panchayati Raj, has launched a pilot program named <strong style=\"color:#0063ae;\">\"Capacity Building for Viksit Panchayat\"</strong> to enhance the capabilities of both elected representatives (such as Sarpanch and Ward Members) and officials (including Secretaries, Gram Rozgar Sevaks, etc.) at the Gram Panchayat level.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">To truly empower local governance and enhance citizens\' quality of life, it\'s crucial to revitalize the Panchayati Raj system by focusing on:</p><div class=\"row g-3 mt-3\"><div class=\"col-md-6\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><i class=\"bi bi-1-circle-fill\" style=\"color:#0063ae;margin-right:10px;\"></i> <strong>Decentralizing powers</strong> to facilitate localized governance</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-left:4px solid #28a745;border-radius:8px;padding:15px;\"><i class=\"bi bi-2-circle-fill\" style=\"color:#28a745;margin-right:10px;\"></i> <strong>Amplifying citizen participation</strong> in local decision-making processes</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-left:4px solid #ffa500;border-radius:8px;padding:15px;\"><i class=\"bi bi-3-circle-fill\" style=\"color:#ffa500;margin-right:10px;\"></i> <strong>Ensuring effective program implementation</strong> and accountability</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(220, 53, 69, 0.1);border-left:4px solid #dc3545;border-radius:8px;padding:15px;\"><i class=\"bi bi-4-circle-fill\" style=\"color:#dc3545;margin-right:10px;\"></i> <strong>Enhancing service delivery</strong> and promoting equitable &amp; sustainable development</div></div></div></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><!-- Short-Term Objectives --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clock-fill\" style=\"color:#0063ae;\"></i></p><h4>Short-Term Objectives</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Establish a robust capacity-building mechanism for Panchayat officials and representatives through targeted training and workshops.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Conduct baseline assessments to capture current competency, institutional knowledge, planning abilities, fund utilization, and citizen perceptions within selected pilot Gram Panchayats.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Develop and deploy technology-enabled solutions (e-learning platform, app, AI-powered chatbot) for standardized training, personalized resources, and real-time tracking of progress.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Implement project modules focused on priority areas like GPDP, financial management, digital literacy, and service delivery.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Achieve measurable milestones: completion of training modules, certification of PRI members, and initial improvements in governance processes and service delivery.</li></ul></div></div><!-- Long-Term Objectives --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);border-left:5px solid #28a745;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-bullseye\" style=\"color:#28a745;\"></i></p><h4>Long-Term Objectives</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Strengthen institutional structures and systems of Panchayats through sustained capacity-building frameworks, enabling decentralized and participatory governance.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Empower Panchayat functionaries to understand community needs, integrate them into development plans, and proactively address challenges leveraging cross-sector resources.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Foster financial self-sufficiency of Panchayats via entrepreneurial activities, improved fund utilization, and income generation from local resources.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Institutionalize technology-driven approaches for continuous professional development and transformation, ensuring responsive, accountable, and citizen-centric governance at the grassroots level.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;left:0;position:absolute;\"></i> Develop a demonstrable and scalable model for strengthening Panchayati Raj governance, enabling nationwide replication and sustainable rural development.</li></ul></div></div></div></div></section><!-- Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Concept Note</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Gist of Concept Note</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The concept note outlines a pilot project aimed at strengthening Panchayati Raj Institutions (PRIs) in India through targeted capacity-building of elected representatives and officials at the Gram Panchayat level. Using the <strong style=\"color:#0063ae;\">Karmayogi competency model</strong>, the project leverages technology platforms like an e-learning portal, mobile app, and AI-powered chatbot to deliver personalized training and track progress.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">This pilot is implemented in <strong style=\"color:#28a745;\">four states</strong> across <strong style=\"color:#28a745;\">60 Panchayats</strong>, using baseline assessments, customized training modules, and participatory learning methods to improve governance, service delivery, and citizen engagement. The activities include roundtables, workshops, experiential learning, and formation of peer circles and action projects to equip PRI members for effective decentralized decision-making.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">A key focus is on <strong style=\"color:#0063ae;\">financial management</strong>, <strong style=\"color:#0063ae;\">access to entitlements</strong>, and fostering innovation for local economic development. By integrating digital tools and participatory practices, the project seeks to create a scalable model for future rural development initiatives.</p><div style=\"background-color:rgba(0, 99, 174, 0.05);border-left:4px solid #0063ae;border-radius:10px;margin-top:25px;padding:20px;\"><p style=\"color:#002b5b;margin:0;\"><i class=\"bi bi-link-45deg\" style=\"color:#0063ae;margin-right:10px;\"></i> <strong>Full Concept Note:</strong> <a style=\"color:#0063ae;text-decoration:none;\" href=\"https://docs.google.com/document/d/1wqFxnfF_5pRvhOsqZC1zsgicYn4r2PUl/edit?usp=sharing&amp;ouid=110959317570635838249&amp;rtpof=true&amp;sd=true\" target=\"_blank\">View Full Document <i class=\"bi bi-box-arrow-up-right\"></i>&nbsp;</a></p></div></div></div></div></section><!-- Proposed Activities & Methodologies Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Proposed Activities &amp; Methodologies</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-calendar-check-fill\" style=\"color:#0063ae;\"></i></p><h4>Project Implementation Approach</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The one-year project primarily engages with elected representatives and Panchayat officials. <strong style=\"color:#0063ae;\">15 panchayats</strong> have been identified from each of the four project pilot states: <strong style=\"color:#28a745;\">Andhra Pradesh, Assam, Gujarat, and Odisha</strong>.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">The project initiated with multiple roundtables with grassroots organisations, knowledge partners, and thematic experts for Panchayats to develop program design with a plan of action. State-level workshops were conducted with relevant stakeholders to discuss the plan and understand their perspective.</p><!-- Baseline Indicators --><div style=\"margin-top:25px;\"><h5 style=\"color:#002b5b;margin-bottom:15px;\"><strong><i class=\"bi bi-clipboard-data-fill\" style=\"color:#0063ae;margin-right:10px;\"></i>Baseline Assessment Indicators</strong></h5><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-1-circle-fill\" style=\"color:#0063ae;\"></i> Existing Competency</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-2-circle-fill\" style=\"color:#28a745;\"></i> Institutional Knowledge</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-3-circle-fill\" style=\"color:#ffa500;\"></i> GPDP Planning &amp; Implementation</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(220, 53, 69, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-4-circle-fill\" style=\"color:#dc3545;\"></i> Fund Utilisation &amp; Documentation</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(108, 117, 125, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-5-circle-fill\" style=\"color:#6c757d;\"></i> Community Participation &amp; Gram Sabha</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-6-circle-fill\" style=\"color:#0063ae;\"></i> Competency Application &amp; Service Delivery</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:8px;padding:15px;\"><i class=\"bi bi-7-circle-fill\" style=\"color:#28a745;\"></i> Citizen Perception of the Panchayat</div></div></div></div><!-- Key Focus Areas --><div style=\"margin-top:30px;\"><h5 style=\"color:#002b5b;margin-bottom:15px;\"><strong><i class=\"bi bi-bullseye\" style=\"color:#0063ae;margin-right:10px;\"></i>Key Focus Areas</strong></h5><div class=\"row g-3\"><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-file-earmark-check-fill\"></i></div><div class=\"karmayogi-milestone-title\">Access to Entitlements</div></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Public Goods &amp; Services</div></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-briefcase-fill\"></i></div><div class=\"karmayogi-milestone-title\">Access to Livelihood</div></div></div><div class=\"col-md-6 col-lg-3\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Social Development</div></div></div></div></div></div></div></div></section><!-- Technology Solutions Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-laptop-fill me-3\" style=\"color:#0063ae;\"></i>Technology Solutions</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- E-Learning Platform --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-top:5px solid #0063ae;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;margin-right:15px;width:60px;\"><i class=\"bi bi-play-circle-fill\"></i></div><h4>E-Learning Platform</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Integrated into <strong style=\"color:#0063ae;\">iGOT</strong>, offers online courses, informational videos, FAQs, podcasts, and learning resources covering critical areas of PRI work. Enables real-time tracking of competency acquisition and progress.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Topics Include:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Gram Panchayat Development Plan (GPDP)</li><li>Conducting Gram Sabha</li><li>Financial Management</li><li>Digital Tools</li><li>Scheme Convergence</li></ul></div></div></div><!-- Capacity Building App --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-top:5px solid #28a745;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;margin-right:15px;width:60px;\"><i class=\"bi bi-phone-fill\"></i></div><h4>Capacity Building App</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Comprehensive mobile application providing structured approach to training delivery, tracking progress, and measuring impact.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Key Features:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Training Management</li><li>User Management</li><li>Assessment &amp; Testing</li><li>Tracking &amp; Monitoring</li><li>Reporting &amp; Analytics</li><li>Notification &amp; Alerts</li></ul></div></div></div><!-- AI-Powered Chatbot --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-top:5px solid #ffa500;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#ffc107;border-radius:50%;color:#fff;display:flex;font-size:1.8rem;height:60px;justify-content:center;margin-right:15px;width:60px;\"><i class=\"bi bi-chat-dots-fill\"></i></div><h4>AI-Powered Chatbot</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Voice-enabled AI chatbot designed to provide personalized support and resolve queries for PRI members. Integrated with Panchayat Acts, rules, and resources.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Functionalities:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Query Resolution</li><li>Resource Recommendation</li><li>Personalized Support</li><li>Community Building</li><li>Progress Tracking</li></ul></div></div></div></div></div></div></section><!-- Action Plan - Three Learning Approaches --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-diagram-3-fill me-3\" style=\"color:#0063ae;\"></i>Action Plan: Three-Part Learning Approach</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(0, 153, 255, 0.05);border-left:5px solid #0063ae;margin-bottom:30px;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-style:normal;\">The project uses the <strong style=\"color:#0063ae;\">Karmayogi competency model</strong>, focusing on practical skills that improve governance at the grassroots level. It follows a <strong style=\"color:#0063ae;\">three-part learning approach</strong>: Self-Learning, Peer Learning, and Experiential Learning.</p></div><div class=\"row g-4\"><!-- Self-Learning --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#0099ff;border-radius:50%;color:#fff;display:flex;font-size:1.5rem;height:50px;justify-content:center;margin-right:15px;width:50px;\"><strong>1</strong></div><h4>Self-Learning</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><strong style=\"color:#0063ae;\">Learning at Your Own Pace</strong></p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:10px;\">Panchayat representatives and officials engage with learning material independently through a mobile app and WhatsApp-based chatbot, ensuring knowledge is accessible anytime, anywhere, and in local languages.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Formats Include:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Booklets and mobile-friendly PDFs</li><li>Short videos in local languages</li><li>Concise, practical guidance</li></ul></div></div></div><!-- Peer Learning --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#20c997;border-radius:50%;color:#fff;display:flex;font-size:1.5rem;height:50px;justify-content:center;margin-right:15px;width:50px;\"><strong>2</strong></div><h4>Peer Learning</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><strong style=\"color:#28a745;\">Learning Together through Exchange</strong></p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:10px;\">Emphasizes the importance of collective wisdom and the exchange of experiences. Panchayat leaders learn from each other\'s successes and strategies through structured platforms.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Platforms Include:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Cluster-based learning circles (5-10 Sarpanchs)</li><li>Workshops and classroom-based learning</li><li>Experience-sharing sessions at block-level meetings</li><li>Master Facilitators leading ToT programs</li></ul></div></div></div><!-- Experiential Learning --><div class=\"col-md-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;height:100%;\"><div class=\"karmayogi-feature-header\"><div style=\"align-items:center;background-color:#ffc107;border-radius:50%;color:#fff;display:flex;font-size:1.5rem;height:50px;justify-content:center;margin-right:15px;width:50px;\"><strong>3</strong></div><h4>Experiential Learning</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><strong style=\"color:#ffa500;\">Learning by Doing</strong></p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:10px;\">Participants apply their skills in real-life situations, becoming active doers rather than passive recipients of knowledge.</p><div style=\"margin-top:15px;\"><p><strong style=\"color:#002b5b;\">Activities Include:</strong></p><ul style=\"color:#6c757d;margin-top:10px;padding-left:20px;\"><li>Village-level action projects</li><li>Field visits to model Panchayats</li><li>Demonstration exercises</li><li>Simulation games (budget planning, resource mapping)</li><li>Gram Panchayat Facilitator (GPF) support</li></ul></div></div></div></div><!-- GPF Information --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);border-left:5px solid #dc3545;margin-top:50px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#dc3545;\"></i></p><h4>Gram Panchayat Facilitator (GPF) Support</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The Commission will deploy a <strong style=\"color:#dc3545;\">Gram Panchayat Facilitator (GPF) for every three Panchayats</strong>. These facilitators work closely with Panchayat representatives and officials to strengthen planning, service delivery, and community engagement. Acting as the bridge between the community and the system, GPFs ensure that knowledge translates into tangible impact at the last mile.</p></div></div></div></section><!-- Chronology Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div style=\"padding-left:40px;position:relative;\"><!-- Timeline Items --><div style=\"background-color:#28a745;border-radius:2px;bottom:0;left:0;position:absolute;top:0;width:3px;\">&nbsp;</div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>Month 1</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Program inception, roundtables, and the development of an action plan with partner organizations and stakeholders; baseline assessments in selected Panchayats.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#0063ae;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(0, 99, 174, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#0063ae;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 1–3</strong></div><div style=\"color:#002b5b;line-height:1.7;\">State-level workshops to refine project modules and finalize implementation and evaluation plans; stakeholder mobilization and role clarity.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 2–3</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Baseline assessments of PRI members, institutional capacity, and community participation; identification of competency gaps.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#28a745;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(40, 167, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#28a745;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 3–5</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Design of competency-based training modules and customized content for classroom and digital delivery; technology platform (app, LMS, chatbot) development and pilot testing.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 5–16</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Full-scale rollout of capacity-building, training, and technology adoption across pilot Panchayats; continuous engagement, monitoring, and user feedback collection.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#ffa500;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(255, 165, 0, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#ffa500;font-size:1.1rem;margin-bottom:8px;\"><strong>Month 10</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Midline survey to evaluate interim outcomes and adjust strategies.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#dc3545;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(220, 53, 69, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#dc3545;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 16–18</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Completion of training rollout, knowledge asset/toolkit creation for Panchayats, and drafting scalability plan based on field learnings.</div></div><div style=\"margin-bottom:30px;position:relative;\"><div style=\"background-color:#6c757d;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px rgba(108, 117, 125, 0.2);height:20px;left:-32px;position:absolute;top:5px;width:20px;\">&nbsp;</div><div style=\"color:#6c757d;font-size:1.1rem;margin-bottom:8px;\"><strong>Months 19–20</strong></div><div style=\"color:#002b5b;line-height:1.7;\">Endline assessment, impact analysis, and final project report preparation.</div></div></div></div></div></div></div></div></section><!-- Key Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-flag-fill me-3\" style=\"color:#0063ae;\"></i>Key Milestones</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-clipboard-check-fill\"></i></div><div class=\"karmayogi-milestone-title\">Baseline &amp; Inception Report</div><div class=\"karmayogi-milestone-label\">Finalization of baseline assessments and project inception documentation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-book-half\"></i></div><div class=\"karmayogi-milestone-title\">Training Modules Development</div><div class=\"karmayogi-milestone-label\">Development of capacity-building framework and tailored training modules</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-phone-fill\"></i></div><div class=\"karmayogi-milestone-title\">Technology Deployment</div><div class=\"karmayogi-milestone-label\">Deployment and testing of app, e-learning platform, and AI-powered chatbot</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-people-fill\"></i></div><div class=\"karmayogi-milestone-title\">Training Delivery</div><div class=\"karmayogi-milestone-label\">Delivery of training programs to PRI members with adoption of technology</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#495057;\"><i class=\"bi bi-graph-up-arrow\"></i></div><div class=\"karmayogi-milestone-title\">Impact Assessments</div><div class=\"karmayogi-milestone-label\">Conduct of midline and endline assessments reporting competency growth</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-handshake\"></i></div><div class=\"karmayogi-milestone-title\">Community Engagement</div><div class=\"karmayogi-milestone-label\">Enhancement of community participation in GPDP planning and governance</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-file-earmark-text-fill\"></i></div><div class=\"karmayogi-milestone-title\">Final Report &amp; Scaling</div><div class=\"karmayogi-milestone-label\">Preparation of final project report and scaling strategy for replication</div></div></div></div></div></div></section><!-- Impact Metrics Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-graph-up-arrow me-3\" style=\"color:#0063ae;\"></i>Impact Metrics</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><!-- Outputs --><div class=\"col-lg-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;height:100%;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-box-fill\" style=\"color:#0063ae;\"></i></p><h4>Outputs</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Number of PRI members trained and certified</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Number of customized training modules delivered</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Volume of user activity on technology platforms</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#0063ae;left:0;position:absolute;\"></i> GPDP plans prepared with community inputs</li></ul></div></div></div><!-- Outcomes --><div class=\"col-lg-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;height:100%;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-trophy-fill\" style=\"color:#28a745;\"></i></p><h4>Outcomes</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#28a745;left:0;position:absolute;\"></i> Improved governance capacity and leadership</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#28a745;left:0;position:absolute;\"></i> Higher proportion of PRIs using digital tools</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#28a745;left:0;position:absolute;\"></i> Increased citizen participation in decision-making</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#28a745;left:0;position:absolute;\"></i> Greater adoption of financial management practices</li></ul></div></div></div><!-- Indicators --><div class=\"col-lg-4\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;height:100%;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-bar-chart-fill\" style=\"color:#ffa500;\"></i></p><h4>Indicators</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Percentage increase in governance capacity scores</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Proportion of Panchayats using digital tools</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Percentage increase in citizen participation</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Improvement in fund utilization rates</li><li style=\"margin-bottom:10px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle\" style=\"color:#ffa500;left:0;position:absolute;\"></i> Level of community satisfaction</li></ul></div></div></div></div></div></div></section><!-- Way Forward Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-arrow-right-circle-fill me-3\" style=\"color:#0063ae;\"></i>Way Forward</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#0063ae;\"></i></p><h4>Scaling Strategy</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Based on the impact assessment and observations from the pilot implementation, the way forward for scaling the capacity-building model involves a <strong style=\"color:#0063ae;\">data-driven, adaptive approach</strong> in collaboration with the <strong style=\"color:#0063ae;\">Ministry of Panchayati Raj (MoPR)</strong>.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">The impact assessment outcomes will provide evidence of the strengths, gaps, and contextual factors influencing the success of the model at the Gram Panchayat level. These learnings will guide decisions whether to replicate the existing model as is or adapt it suitably for diverse regional contexts.</p><div style=\"margin-top:25px;\"><h5 style=\"color:#002b5b;margin-bottom:15px;\"><strong><i class=\"bi bi-list-check\" style=\"color:#0063ae;margin-right:10px;\"></i>Key Priorities</strong></h5><div class=\"row g-3\"><div class=\"col-md-6\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;margin-right:10px;\"></i> <strong>Institutionalizing</strong> technology-enabled capacity building</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-left:4px solid #28a745;border-radius:8px;padding:15px;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;margin-right:10px;\"></i> <strong>Expanding</strong> training reach across states</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-left:4px solid #ffa500;border-radius:8px;padding:15px;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#ffa500;margin-right:10px;\"></i> <strong>Enhancing</strong> participatory governance mechanisms</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(220, 53, 69, 0.1);border-left:4px solid #dc3545;border-radius:8px;padding:15px;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#dc3545;margin-right:10px;\"></i> <strong>Developing</strong> standardized yet flexible training modules</div></div></div></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:25px;\">MoPR engagement will be intensified to secure policy endorsement, facilitate resource mobilization, and foster partnerships with state governments and implementation agencies for national roll-out. Continuous feedback loops, periodic evaluations, and technical support structures will be established to sustain and iterate the approach for evolving governance challenges.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">Overall, the intention is to ensure the capacity-building initiative evolves from a pilot to a <strong style=\"color:#0063ae;\">scalable, sustainable national program</strong> that strengthens Panchayat governance, empowerment, and citizen-centric development systematically and inclusively across India.</p></div></div></div></section>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 68, 110, 'en', 0, '<!-- Vision Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4 align-items-start\"><!-- Vision Content --><div class=\"col-lg-8\"><h2 class=\"karmayogi-section-title\" style=\"font-size:1.8rem;margin-bottom:25px;text-align:left;\"><i class=\"bi bi-eye-fill me-3\" style=\"color:#0063ae;\"></i>Vision</h2><div class=\"karmayogi-quote-block\" style=\"background-color:rgba(248, 250, 252, 0.9);border-left:5px solid #0063ae;height:100%;\"><div class=\"karmayogi-quote-icon\"><i class=\"bi bi-lightbulb-fill\"></i></div><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;\">Cities in India occupy a central position for propelling India\'s vision of becoming <strong style=\"color:#0063ae;\">\"Viksit Bharat\" by 2047</strong> since they are contributing <strong style=\"color:#0063ae;\">65% to the overall GDP</strong>. Over the past two decades, urban development schemes have strengthened municipal capacities through infrastructure development and reforms. However, scheme-specific capacity-building efforts are often limited to aligned specific objectives with focused target group.</p><p class=\"karmayogi-quote-text\" style=\"color:#002b5b;font-size:0.95rem;font-style:normal;line-height:1.7;margin-top:12px;\">Keeping in mind the important role of cities in nation development and learnings gained from legacy capacity building initiatives, the <strong style=\"color:#0063ae;\">Capacity Building Commission under Mission Karmyogi</strong> expanded its reach from central government ministries and departments to ULBs to develop a comprehensive capacity development ecosystem for all the <strong style=\"color:#28a745;\">4800+ Urban Local Bodies</strong>, which will eventually lead to improved local governance &amp; service delivery.</p></div></div><!-- Important Information Section --><div class=\"col-lg-4\"><div style=\"background-color:#ffffff;border-radius:15px;border:3px solid #0063ae;box-shadow:0 6px 20px rgba(0, 0, 0, 0.15);display:flex;flex-direction:column;height:100%;overflow:hidden;\"><!-- Blue Header Section --><div style=\"background-color:#0063ae;flex-shrink:0;padding:15px 20px;\"><h4 style=\"align-items:center;color:#ffffff;display:flex;font-size:1.1rem;gap:10px;margin:0;\"><strong><i class=\"bi bi-info-circle-fill\" style=\"color:#ffffff;font-size:1.2rem;\"></i> Initiative Overview</strong></h4></div><!-- Info Section --><div style=\"background-color:#ffffff;display:flex;flex-direction:column;flex:1;justify-content:space-between;padding:18px 20px;\"><div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-building\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Target ULBs</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">4800+ Urban Local Bodies</div></div></div></div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-people-fill\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Municipal Functionaries</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">Over 15 lakh municipal functionaries</div></div></div></div><div style=\"margin-bottom:16px;\"><div style=\"align-items:flex-start;display:flex;gap:8px;margin-bottom:6px;\"><p><i class=\"bi bi-graph-up-arrow\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">GDP Contribution</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">65% of India\'s GDP</div></div></div></div><div style=\"margin-bottom:0;\"><div style=\"align-items:flex-start;display:flex;gap:8px;\"><p><i class=\"bi bi-bullseye\" style=\"color:#0063ae;flex-shrink:0;font-size:1rem;margin-top:3px;\"></i></p><div style=\"flex:1;\"><p><strong style=\"color:#002b5b;display:block;font-size:0.9rem;margin-bottom:4px;\">Approach</strong></p><div style=\"color:#6c757d;font-size:0.85rem;line-height:1.4;\">Demand-driven, role-based capacity building</div></div></div></div></div></div></div></div></div></div></div></section><!-- Objectives Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-bullseye me-3\" style=\"color:#002b5b;\"></i>Objectives</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Strategic Approach</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">This initiative presents a strategic opportunity to institutionalize a <strong style=\"color:#0063ae;\">demand-driven, role-based approach</strong> to capacity building across Urban Local Bodies (ULBs) in India. It seeks to move beyond traditional training paradigms by fostering a system responsive to the practical and evolving needs of ULBs, thereby supporting the development of a future-ready urban workforce.</p></div><!-- Short-Term Objectives --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clock-fill\" style=\"color:#0063ae;\"></i></p><h4>Objectives</h4></div><div class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\"><ul style=\"list-style:none;padding-left:0;\"><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Strengthen the overall capacity-building ecosystem by establishing institutional mechanisms, expanding access to high-quality e-learning resources, and ensuring seamless integration with digital platforms.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Create a network of Subject Matter Experts (SMEs) to deliver contextualized and role-specific training that aligns with the operational realities of ULBs.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Build the competencies of ULB officials to enhance last-mile service delivery, transparency, and citizen-centric governance.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Transition from rule-based to role-based management by identifying key roles within ULB structures and mapping them against domain, functional, and behavioural competencies.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Support the development of competency-aligned courses and structured learning pathways tailored to equip urban staff with the tools, knowledge, and skills required to deliver inclusive, efficient, and accountable services at the local level.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Design targeted interventions that empower personnel to perform their responsibilities effectively and accountably.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Address identified capacity gaps through systematic and scalable capacity building mechanisms.</li><li style=\"margin-bottom:12px;padding-left:25px;position:relative;\"><i class=\"bi bi-check-circle-fill\" style=\"color:#0063ae;left:0;position:absolute;\"></i> Transform ULBs from input-based entities into future-ready institutions that anchor India\'s vision of Viksit Bharat@2047.</li></ul></div></div></div></div></section><!-- Concept Note Section --><section class=\"karmayogi-section-fullwidth karmayogi-concept-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-text-fill me-3\" style=\"color:#0063ae;\"></i>Conceptual Framework</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(248, 250, 252, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Concept Overview</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">The Capacity Building of Urban Local Bodies initiative under Mission Karmayogi seeks to create a <strong style=\"color:#0063ae;\">robust, demand-driven, and role-based capacity development ecosystem</strong> for over <strong style=\"color:#28a745;\">4800 ULBs in India</strong>. Recognising the critical role of cities in driving economic growth and citizen welfare, this initiative moves beyond scheme-specific training to institutionalize structured and scalable mechanisms for enhancing municipal governance and service delivery.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">It leverages the <strong style=\"color:#0063ae;\">iGOT Karmayogi platform</strong> to ensure speed, scale, and equitable access to high-quality courses, while simultaneously strengthening the fragmented training ecosystem through standardization, expert networks, and world-class pedagogy. The initiative ultimately aims to empower <strong style=\"color:#28a745;\">over 15 lakh municipal functionaries</strong> with the functional, domain, and behavioural competencies required to deliver inclusive, transparent, and citizen-centric services.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:15px;\">By integrating technology, performance-linked learning, and a focus on sustainability, the program envisions transforming ULBs from input-based entities into <strong style=\"color:#0063ae;\">future-ready institutions</strong> that anchor India\'s vision of <strong style=\"color:#0063ae;\">Viksit Bharat@2047</strong>.</p></div></div></div></section><!-- Chronology of Events Section --><section class=\"karmayogi-section-fullwidth karmayogi-milestones-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-calendar-event me-3\" style=\"color:#0063ae;\"></i>Chronology of Events</h2><div class=\"karmayogi-content-wrapper\"><div class=\"row g-4\"><div class=\"col-12\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-info-circle-fill\" style=\"color:#0063ae;\"></i></p><h4>Pilot Phase Implementation</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\">CBC conducted a pilot for <strong style=\"color:#0063ae;\">7 (seven) selected ULBs</strong> (Pune, Ahmedabad, NDMC, Nagpur, Rajkot, Mysore and Bhubaneshwar), in collaboration with MOHUA, to tackle the crucial challenge of enhancing the capacity of these ULBs. A set of over <strong style=\"color:#28a745;\">120 areas of skilling</strong> in the areas of Administrative &amp; Governance, Technical &amp; Engineering, Technology, Finance, Project Management, Behavioral tracks were identified.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\">Based on this, the ULBs prepared their <strong style=\"color:#0063ae;\">Annual Capacity Building Plans (ACBPs)</strong> and with assistance prepared job descriptions, competency maps and linked trainings for each Municipal role. CBC is working closely with these ULBs for the time-bound implementation of the ACBPs, with officials leveraging iGOT to undergo training.</p><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\">The findings suggest that a large number of behavioral, functional and domain competencies are common across all ULBs, so the development of digital courses and training programs can be started right away since they can be applied to all ULBs. The pilot suggests that a <strong style=\"color:#0063ae;\">demand-driven, bottom-up, role-based capacity building approach</strong> will have a sustainable impact on municipal performance.</p><!-- Challenges Identified --><div style=\"background-color:rgba(0, 99, 174, 0.05);border-left:4px solid #0063ae;border-radius:10px;margin-top:30px;padding:20px;\"><h5 style=\"color:#002b5b;margin-bottom:15px;\"><strong><i class=\"bi bi-exclamation-triangle-fill\" style=\"color:#0063ae;margin-right:10px;\"></i>Challenges Identified</strong></h5><div class=\"row g-3\"><div class=\"col-md-6\"><div style=\"background-color:rgba(255, 255, 255, 0.8);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><i class=\"bi bi-speedometer2\" style=\"color:#0063ae;margin-right:10px;\"></i> <strong>Speed &amp; Scale:</strong> Capacity building must be done with speed and at scale for 4700+ ULBs (over 10+ lakh municipal functionaries in India, each with a varied level of resources and skills. iGOT offers the fastest way to train ULB staff.</div></div><div class=\"col-md-6\"><div style=\"background-color:rgba(255, 255, 255, 0.8);border-left:4px solid #28a745;border-radius:8px;padding:15px;\"><i class=\"bi bi-puzzle-fill\" style=\"color:#28a745;margin-right:10px;\"></i> <strong>Fragmented Ecosystem:</strong> The training (supply) ecosystem in municipal domain is highly fragmented with varying degrees of faculty quality, pedagogy, scale, content and access.</div></div><div class=\"col-md-12\"><div style=\"background-color:rgba(255, 255, 255, 0.8);border-left:4px solid #ffa500;border-radius:8px;padding:15px;\"><i class=\"bi bi-diagram-3-fill\" style=\"color:#ffa500;margin-right:10px;\"></i> <strong>Lack of Formal Structures:</strong> There is a lack of formal structures and Job Roles-to-Competency registries, which will prevent a consistent application of capacity building strategies. A formal competency framework with access to role-to-skill map, training linkage and performance assessment is being developed in concert with Karmayogi Competency Model.</div></div></div></div><!-- Outcomes Defined --><div style=\"margin-top:30px;\"><h5 style=\"color:#002b5b;margin-bottom:15px;\"><strong><i class=\"bi bi-check-circle-fill\" style=\"color:#28a745;margin-right:10px;\"></i>Outcomes Defined Based on Learnings</strong></h5><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><i class=\"bi bi-arrow-left-right\" style=\"color:#0063ae;margin-right:10px;\"></i> Move urban capacity building from supply-driven to demand-driven approach by ULBs</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-left:4px solid #28a745;border-radius:8px;padding:15px;\"><i class=\"bi bi-link-45deg\" style=\"color:#28a745;margin-right:10px;\"></i> Linking job-roles to performance and continuous improvement</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-left:4px solid #ffa500;border-radius:8px;padding:15px;\"><i class=\"bi bi-building-check\" style=\"color:#ffa500;margin-right:10px;\"></i> Strengthen the urban training (supply) ecosystem in India with world-class pedagogy and faculty</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(220, 53, 69, 0.1);border-left:4px solid #dc3545;border-radius:8px;padding:15px;\"><i class=\"bi bi-laptop\" style=\"color:#dc3545;margin-right:10px;\"></i> Higher integration of technology in urban capacity building ecosystem for access, equity and quality of skilling</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(108, 117, 125, 0.1);border-left:4px solid #6c757d;border-radius:8px;padding:15px;\"><i class=\"bi bi-people\" style=\"color:#6c757d;margin-right:10px;\"></i> Move ULBs from inputs based to citizen oriented/service-oriented governance</div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><i class=\"bi bi-handshake\" style=\"color:#0063ae;margin-right:10px;\"></i> These initiatives will be taken forward in collaboration with MoHUA and its affiliated training institutes</div></div></div></div></div></div></div></div></div></section><!-- Key Milestones Section --><section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-flag-fill me-3\" style=\"color:#0063ae;\"></i>Key Milestones</h2><div class=\"karmayogi-content-wrapper\"><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-clipboard-check-fill\" style=\"color:#0063ae;\"></i></p><h4>7 Annual Capacity Building Plans (ACBPs) Prepared and Approved</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\">The following Urban Local Bodies (ULBs) have finalised and received approval for their ACBPs:</p><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Ahmedabad Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Bhubaneswar Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#ffc107;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Mysuru City Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#e74c3c;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Nagpur Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#495057;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">New Delhi Municipal Council (NDMC)</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#0099ff;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Pune Municipal Corporation</div></div></div><div class=\"col-md-6 col-lg-4\"><div class=\"karmayogi-milestone-card high-contrast-border\"><div class=\"karmayogi-milestone-icon\" style=\"background-color:#20c997;\"><i class=\"bi bi-building\"></i></div><div class=\"karmayogi-milestone-title\">Rajkot Municipal Corporation</div></div></div></div></div></div></div></section><!-- Key Achievements Section --><section class=\"karmayogi-section-fullwidth karmayogi-objectives-section\"><div class=\"container\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-trophy-fill me-3\" style=\"color:#0063ae;\"></i>Key Achievements</h2><div class=\"karmayogi-content-wrapper\"><!-- Platform Onboarding --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #0063ae;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-people-fill\" style=\"color:#0063ae;\"></i></p><h4>Platform Onboarding</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Over <strong style=\"color:#0063ae;\">1,55,000+ ULB officials</strong> have been successfully onboarded onto the iGOT Karmayogi Bharat platform, with more in the process of joining.</p></div><!-- Course Development --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #28a745;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-book-half\" style=\"color:#28a745;\"></i></p><h4>Course Development</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:15px;\">A total of <strong style=\"color:#28a745;\">154 curated courses</strong> is currently available on iGOT for ULB officials, including:</p><div class=\"row g-3\"><div class=\"col-md-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-radius:8px;padding:15px;text-align:center;\"><div style=\"color:#0063ae;font-size:2rem;margin-bottom:5px;\"><strong>60</strong></div><div style=\"color:#002b5b;\"><strong>Functional Courses</strong></div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-radius:8px;padding:15px;text-align:center;\"><div style=\"color:#28a745;font-size:2rem;margin-bottom:5px;\"><strong>64</strong></div><div style=\"color:#002b5b;\"><strong>Domain Courses</strong></div></div></div><div class=\"col-md-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-radius:8px;padding:15px;text-align:center;\"><div style=\"color:#ffa500;font-size:2rem;margin-bottom:5px;\"><strong>30</strong></div><div style=\"color:#002b5b;\"><strong>Behavioural Courses</strong></div></div></div></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:20px;\"><strong style=\"color:#28a745;\">22 domain-specific courses</strong> have been launched on iGOT, and <strong style=\"color:#28a745;\">13 more high-impact courses</strong> are currently under development. The courses launched so far have received an <strong style=\"color:#ffa500;\">average user rating of 4.3 stars</strong>.</p></div><!-- State-Level Workshops --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #ffa500;margin-bottom:30px;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-calendar-event-fill\" style=\"color:#ffa500;\"></i></p><h4>State-Level Workshops</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-bottom:20px;\"><strong style=\"color:#ffa500;\">5 state-level workshops</strong> on \"Capacity Building of Urban Local Bodies under Mission Karmayogi\" were successfully organized:</p><div class=\"row g-3\"><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(0, 99, 174, 0.1);border-left:4px solid #0063ae;border-radius:8px;padding:15px;\"><div style=\"color:#0063ae;margin-bottom:5px;\"><strong>Assam</strong></div><div style=\"color:#6c757d;font-size:0.9rem;\">December - 125+ ULB officials and State UDD representatives</div></div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(40, 167, 69, 0.1);border-left:4px solid #28a745;border-radius:8px;padding:15px;\"><div style=\"color:#28a745;margin-bottom:5px;\"><strong>Andhra Pradesh</strong></div><div style=\"color:#6c757d;font-size:0.9rem;\">June - 175+ ULB officials and State UDD representatives</div></div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(255, 165, 0, 0.1);border-left:4px solid #ffa500;border-radius:8px;padding:15px;\"><div style=\"color:#ffa500;margin-bottom:5px;\"><strong>Haryana</strong></div><div style=\"color:#6c757d;font-size:0.9rem;\">June - 90+ ULB officials</div></div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(220, 53, 69, 0.1);border-left:4px solid #dc3545;border-radius:8px;padding:15px;\"><div style=\"color:#dc3545;margin-bottom:5px;\"><strong>Uttar Pradesh</strong></div><div style=\"color:#6c757d;font-size:0.9rem;\">24th &amp; 25th June - 750+ ULB officials</div></div></div><div class=\"col-md-6 col-lg-4\"><div style=\"background-color:rgba(108, 117, 125, 0.1);border-left:4px solid #6c757d;border-radius:8px;padding:15px;\"><div style=\"color:#6c757d;margin-bottom:5px;\"><strong>Odisha</strong></div><div style=\"color:#6c757d;font-size:0.9rem;\">23rd July - 100+ ULB officials</div></div></div></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;margin-top:20px;\">Representatives from <strong style=\"color:#ffa500;\">1200+ ULBs</strong> participated in the above workshops.</p></div><!-- Framework Development --><div class=\"karmayogi-feature-block\" style=\"background-color:rgba(240, 248, 255, 0.95);border-left:5px solid #dc3545;\"><div class=\"karmayogi-feature-header\"><p><i class=\"bi bi-diagram-3-fill\" style=\"color:#dc3545;\"></i></p><h4>Framework Development</h4></div><p class=\"karmayogi-feature-desc\" style=\"line-height:1.8;\">Identified and updated <strong style=\"color:#dc3545;\">125 unique designations</strong> across <strong style=\"color:#dc3545;\">25 departments</strong> in the developed Role Aligned Competency Enhancement (RACE) Framework. Comprehensive data mapping is underway to develop a dictionary of Profiles-Roles &amp; Responsibilities-competencies-Training needs for municipal staff that can be translated into an application to automate capacity building planning and implementation. A total of <strong style=\"color:#dc3545;\">65 competencies</strong>, across functional, domain and behavioural, have been defined for the ULBs capacity building.</p></div></div></div></section>', '', 'full_html'),
('page', 0, 74, 118, 'en', 0, '<section class=\"container py-4\"><div class=\"row\"><div class=\"col-lg-12\"><div class=\"content-section\"><!-- PDF Links Section --><div class=\"mb-5 pdf-links-section\"><div class=\"pdf-link-item\"><a class=\"pdf-link-title pdf-link-sop\" href=\"img/MissionKarmayogi2_SOP.pdf\" target=\"_blank\"><i class=\"fas fa-file-pdf pdf-icon\"></i> Standard Operating Procedure (SOP) for States &amp; UTs&nbsp;</a></div></div><!-- Mission Karmayogi State Team Contact Details Section --><div class=\"mb-5\"><h2 class=\"contact-details-heading mb-4\">Mission Karmayogi State Team Contact Details</h2><!-- Central Team Section --><div class=\"mb-5\"><h2 class=\"section-title mb-4\">Central Team</h2><div class=\"mou-status-table-wrapper\"><div class=\"table-responsive\"><table class=\"table mou-status-table\" id=\"centralTeamTable\"><thead><tr><th>Designation</th><th>Name</th><th>Contact</th></tr></thead><tbody><tr><td>Principal Advisor</td><td>Chandralekha Mukherjee</td><td>98913 40077</td></tr><tr><td>Advisor</td><td>Ranu Mookerjee</td><td>88600 40337</td></tr><tr><td>Advisor</td><td>Mustafa Rasheed</td><td>80174 13009</td></tr><tr><td>PMU Lead</td><td>Sonu Kandpal</td><td>9140211905</td></tr></tbody></table></div></div></div><!-- State/UTs Team Section --><div class=\"mb-5\"><h2 class=\"section-title mb-4\">State/UTs Team</h2><div class=\"mou-status-table-wrapper\"><div class=\"table-responsive\"><table class=\"table mou-status-table\" id=\"statesContactTable\"><thead><tr><th>S.No</th><th>State</th><th>Programme Coordinator<br>(Karmayogi Saarthi)</th><th>CBC SPoC</th><th>Contact &amp; Email</th><th>Assistant Manager<br>(Karmayogi Bharat-SPV)</th><th>Contact &amp; Email</th></tr></thead><tbody><tr><td>1</td><td>Andaman &amp; Nicobar Island</td><td>Shipra Singh</td><td>Shipra Singh</td><td>8826393459<br><a href=\"mailto:shiprasingh.cbc@gmail.com\">shiprasingh.cbc@gmail.com</a></td><td>Henry</td><td>6380706234<br><a href=\"mailto:vhenryarokiaraj.kb@kar