('page', 0, 81, 159, 'en', 0, '<p><a class=\"use-ajax opportunity-btn\" href=\"/cbc/form/feedback\" data-dialog-type=\"modal\">Submit Here&nbsp;</a></p><p><a class=\"use-ajax opportunity-btn\" href=\"/cbc/form/feedback\" data-dialog-type=\"modal\" data-dialog-options=\"{&quot;width&quot;:600}\">Submit Here <i class=\"fas fa-arrow-right\"></i>&nbsp;</a></p><p><a class=\"webform-dialog webform-dialog-normal button\" href=\"/cbc/form/feedback\">Test Normal</a></p><section class=\"join-mission-section\"><div class=\"container\"><!-- Introduction Section --><div class=\"row justify-content-center mb-5\"><div class=\"col-lg-12\"><div class=\"mission-karmayogi-header mb-2 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">We welcome passionate individuals and organizations to join us in this transformative journey...</h2></div></div></div><!-- Opportunity Cards Section --><div class=\"row justify-content-center g-4 mb-5 join-opportunity-cards-row\"><!-- For Organisations / SMEs Card --><div class=\"col-lg-6 col-md-6\"><div class=\"join-opportunity-card high-contrast-border\"><div class=\"opportunity-card-header\"><div class=\"opportunity-icon-wrapper\"><i class=\"fas fa-users\"></i></div><h3 class=\"opportunity-title\">For Organisations</h3></div><div class=\"opportunity-card-body\"><p class=\"opportunity-description\">Collaborate with us to strengthen capacity building eco-system and support our initiatives. We welcome partnerships with organizations and subject matter experts who can contribute to our mission.</p><div class=\"opportunity-features\"><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Knowledge Partnerships</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Technology Solutions</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Training Support</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Resource Sharing</span></div><div cla