>Please upload your CV (PDF, DOC, or DOCX format, max 5MB)</small></div><div class=\"mb-3\"><label class=\"form-label\" for=\"ind-contact\">Contact Details <span class=\"text-danger\">*</span></label> <input class=\"form-control-enhanced\" type=\"text\" id=\"ind-contact\" name=\"ind-contact\" placeholder=\"Phone number, Email, or other contact information\" required=\"\"></div><div class=\"mb-3\"><label class=\"form-label\" for=\"ind-address\">Address <span class=\"text-danger\">*</span></label> <textarea class=\"form-control-enhanced\" id=\"ind-address\" name=\"ind-address\" rows=\"3\" placeholder=\"Your complete address\" required=\"\"></textarea></div><div class=\"mb-4\"><label class=\"form-label\" for=\"ind-linkedin\">LinkedIn URL</label> <input class=\"form-control-enhanced\" type=\"url\" id=\"ind-linkedin\" name=\"ind-linkedin\" placeholder=\"https://www.linkedin.com/in/yourprofile\"></div><div class=\"text-center\"><button class=\"btn-submit-enhanced\" type=\"submit\">\r\n                                                                                                                                                                                                                                                              <span>Submit</span>\r\n                                                                                                                                                                                                                                                              <i class=\"fas fa-paper-plane\"></i>\r\n                                                                                                                                                                                                                                                            </button></div></form></div></div></div></div><p><script>\r\n                // Ensure modals are hidden on page load\r\n                document.addEventListener(\'DOMContentLoaded\', function() {\r\n                  // Initialize modals as hidden\r\n                  const orgModal = document.getElementById(\'organizationModal\');\r\n                  const indModal = document.getElementById(\'individualModal\');\r\n                  \r\n                  if (orgModal) {\r\n                    orgModal.style.display = \'none\';\r\n                  }\r\n                  if (indModal) {\r\n                    indModal.style.display = \'none\';\r\n                  }\r\n                  \r\n                  // Form submission handlers\r\n                  const orgForm = document.getElementById(\'organizationForm\');\r\n                  const indForm = document.getElementById(\'individualForm\');\r\n                  \r\n                  if (orgForm) {\r\n                    orgForm.addEventListener(\'submit\', function(e) {\r\n                      e.preventDefault();\r\n                      // Add your form submission logic here\r\n                      alert(\'Organization form submitted successfully!\');\r\n                      closeOrganizationModal();\r\n                    });\r\n                  }\r\n                  \r\n                  if (indForm) {\r\n                    indForm.addEventListener(\'submit\', function(e) {\r\n                      e.preventDefault();\r\n                      // Add your form submission logic here\r\n                      alert(\'Individual form submitted successfully!\');\r\n                      closeIndividualModal();\r\n                    });\r\n                  }\r\n                });\r\n                // Modal functions\r\n                function openOrganizationModal() {\r\n                  const modal = document.getElementById(\'organizationModal\');\r\n                  if (modal) {\r\n                    modal.style.display = \'flex\';\r\n                    document.body.classList.add(\'modal-open\');\r\n                  }\r\n                }\r\n                function closeOrganizationModal() {\r\n                  const modal = document.getElementById(\'organizationModal\');\r\n                  if (modal) {\r\n                    modal.style.display = \'none\';\r\n                    document.body.classList.remove(\'modal-open\');\r\n                  }\r\n                }\r\n                function openIndividualModal() {\r\n                  const modal = document.getElementById(\'individualModal\');\r\n                  if (modal) {\r\n                    modal.style.display = \'flex\';\r\n                    document.body.classList.add(\'modal-open\');\r\n                  }\r\n                }\r\n                function closeIndividualModal() {\r\n                  const modal = document.getElementById(\'individualModal\');\r\n                  if (modal) {\r\n                    modal.style.display = \'none\';\r\n                    document.body.classList.remove(\'modal-open\');\r\n                  }\r\n                }\r\n                // Close modal on Escape key\r\n                document.addEventListener(\'keydown\', function(event) {\r\n                  if (event.key === \'Escape\') {\r\n                    closeOrganizationModal();\r\n                    closeIndividualModal();\r\n                  }\r\n                });\r\n                </script></p>', '', 'full_html');
INSERT INTO `node_revision__body` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `body_value`, `body_summary`, `body_format`) VALUES
('page', 0, 81, 174, 'en', 0, '<section class=\"join-mission-section\"><div class=\"container\"><div class=\"row justify-content-center mb-5\"><div class=\"col-lg-12\"><div class=\"mission-karmayogi-header mb-2 py-4 px-3 rounded text-center\"><h2 class=\"mb-0 fw-bold\">We welcome passionate individuals and organizations to join us in this transformative journey...</h2></div></div></div><!-- Opportunity Cards Section --><div class=\"row justify-content-center g-4 mb-5 join-opportunity-cards-row\"><!-- For Organisations / SMEs Card --><div class=\"col-lg-6 col-md-6\"><div class=\"join-opportunity-card high-contrast-border\"><div class=\"opportunity-card-header\"><div class=\"opportunity-icon-wrapper\"><i class=\"fas fa-users\"></i></div><h3 class=\"opportunity-title\">For Organisations</h3></div><div class=\"opportunity-card-body\"><p class=\"opportunity-description\">Collaborate with us to strengthen capacity building eco-system and support our initiatives. We welcome partnerships with organizations and subject matter experts who can contribute to our mission.</p><div class=\"opportunity-features\"><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Knowledge Partnerships</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Technology Solutions</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Training Support</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Resource Sharing</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Expert Support</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Content Development</span></div></div></div><div class=\"opportunity-card-footer\"><a class=\"opportunity-btn\" href=\"#\" onclick=\"openOrganizationModal(); return false;\">Submit Here <i class=\"fas fa-arrow-right\"></i>&nbsp;</a></div></div></div><!-- Career Opportunities Card --><div class=\"col-lg-6 col-md-6\"><div class=\"join-opportunity-card career-opportunity-card high-contrast-border\"><div class=\"opportunity-card-header\"><div class=\"opportunity-icon-wrapper\"><i class=\"fas fa-briefcase\"></i></div><h3 class=\"opportunity-title\">For Individuals</h3></div><div class=\"opportunity-card-body\"><p class=\"opportunity-description\">Join our team and work on meaningful projects that impact governance and public service delivery. Be part of a dynamic organization committed to transforming civil service capacity building.</p><div class=\"opportunity-features\"><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Subject Matter Expert</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Advisor Role</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Consultant Role</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Internship Program</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Karmayogi Saarthis</span></div><div class=\"feature-item\"><i class=\"fas fa-check-circle\"></i> <span>Research&nbsp;</span></div></div></div><div class=\"opportunity-card-footer\"><a class=\"opportunity-btn\" href=\"#\" onclick=\"openIndividualModal(); return false;\">Submit Here <i class=\"fas fa-arrow-right\"></i>&nbsp;</a></div></div></div></div><!-- Call to Action Section --><div class=\"row justify-content-center\"><div class=\"col-lg-6\"><div class=\"join-cta-section\"><h3 class=\"cta-title\">Ready to Make a Difference?</h3><p class=\"cta-text\">Join us in building a competent civil service rooted in Indian ethos. Together, we can transform public service delivery across India.</p><div class=\"cta-buttons\"><a class=\"cta-btn-primary\" href=\"#/contact\"><i class=\"fas fa-envelope\"></i> Contact Us </a><a class=\"cta-btn-secondary\" href=\"#/about/about-cbc\"><i class=\"fas fa-info-circle\"></i> Learn More&nbsp;</a></div>