('page', 0, 82, 133, 'en', 0, '<header><div class=\"top-bar\"><div class=\"container-fluid d-flex justify-content-between align-items-center flex-wrap px-3\"><div class=\"d-flex align-items-center\"><p><a href=\"#app-content\">Skip to main content</a>| <a class=\"header-border\" href=\"#\">Screen Reader</a></p><div class=\"dropdown header-border\"><ul class=\"dropdown-menu\" aria-labelledby=\"languageDropdown\"><li><a class=\"dropdown-item\" href=\"#\">हिंदी</a></li><li><a class=\"dropdown-item\" href=\"#\">English</a></li></ul></div></div><div class=\"d-flex align-items-center mt-2 mt-md-0\"><img class=\"access-icon\" src=\"img/accessability.png\" alt=\"Accessibility Options - Click to Open\" role=\"button\" tabindex=\"0\" title=\"Open Accessibility Options (Alt+A)\"><div class=\"search-wrapper\"><input type=\"text\" placeholder=\"Search...\"> <i class=\"bi bi-search\"></i></div></div></div></div><nav class=\"navbar high-contrast-border navbar-expand-lg navbar-light custom-navbar p-1 px-2\"><div class=\"container-fluid navigation-oprions px-1\"><p><button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarNav\" aria-controls=\"navbarNav\" aria-expanded=\"false\" aria-label=\"Toggle navigation\">\r\n          <span class=\"navbar-toggler-icon\"></span>\r\n        </button></p><div class=\"collapse navbar-collapse\" id=\"navbarNav\"><ul class=\"navbar-nav mb-2 mb-lg-0 nav-rounded\"><li class=\"nav-item\"><a class=\"nav-link\" href=\"index.html\">Home</a></li><li class=\"nav-item dropdown\"><a class=\"nav-link dropdown-toggle\" href=\"pages/about/about-cbc.html\" id=\"aboutDropdown\" role=\"button\" data-bs-toggle=\"dropdown\" aria-expanded=\"false\">About Us </a><ul class=\"dropdown-menu\" aria-labelledby=\"aboutDropdown\"><li><a class=\"dropdown-item\" href=\"pages/about/about-cbc.html\">About CBC</a></li><li><a class=\"dropdown-item\" href=\"pages/about/know-your-cbc.html\">Know Your CBC</a></li><li><a class=\"dropdown-item