('page', 0, 82, 143, 'en', 0, '<section class=\"container py-5\"><div class=\"row\"><div class=\"col-12\"><div class=\"content-section\"><h2 class=\"section-main-heading mt-5 mb-4\">Knowledge Partnership Overview</h2><div class=\"knowledge-partnership-box mb-5\"><div class=\"knowledge-partnership-header\"><h3>Capacity Building Commission – Knowledge Partnership</h3><div class=\"knowledge-partnership-logo\"><img class=\"cbc-logo-img\" src=\"/cbc/sites/default/files/2025-12/cbc_logo.png\" alt=\"CBC Logo\"><div class=\"logo-text\">CAPACITY BUILDING</div></div></div><div class=\"row g-4 mt-3\"><div class=\"col-md-4\"><div class=\"knowledge-partnership-item\"><div class=\"knowledge-icon-box knowledge-icon-what\"><i class=\"fas fa-file-alt\"></i></div><h4 class=\"knowledge-label\">WHAT</h4><p class=\"knowledge-description\">Knowledge Partnership enables institutions to become a part of the pool of expert knowledge providers for various areas of capacity building exercises.</p></div></div><div class=\"col-md-4\"><div class=\"knowledge-partnership-item\"><div class=\"knowledge-icon-box knowledge-icon-why\"><i class=\"fas fa-bullseye\"></i></div><h4 class=\"knowledge-label\">WHY</h4><p class=\"knowledge-description\">To build, develop, &amp; enhance knowledge resource availability for the civil servants for achievement of common national goals.</p></div></div><div class=\"col-md-4\"><div class=\"knowledge-partnership-item\"><div class=\"knowledge-icon-box knowledge-icon-who\"><i class=\"fas fa-users\"></i></div><h4 class=\"knowledge-label\">WHO</h4><p class=\"knowledge-description\">Knowledge Partnerships hosts a group of eminent institutions who have demonstrated excellence in research, knowledge development and other allied areas.</p></div></div></div></div></div></div></div></section><style>\r\n/* Knowledge Partnership Box */\r\n.knowledge-partnership-box {\r\n  background: linear-gradient(135deg, #00569A 0%, #0063ae 100%);\r\n  border-radius: 12px;\r\n  padding: 30px;\r\