('page', 0, 83, 144, 'en', 0, '<!-- Contact Information Section --><div class=\"contact-info-wrapper py-5\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><div class=\"row\"><div class=\"col-12\"><div class=\"contact-intro-section\"><div class=\"contact-intro-icon\"><i class=\"fas fa-handshake\"></i></div><h2 class=\"contact-intro-title\">We\'re Here to Assist You</h2><p class=\"contact-intro-text\">Get in touch with the Capacity Building Commission. Our team is ready to assist you with any questions, inquiries, or support you may need regarding our initiatives, programs, and services.</p><div class=\"contact-intro-divider\">&nbsp;</div></div></div></div><div class=\"row g-4 mt-4 justify-content-center\"><div class=\"col-lg-4 col-md-6\"><div class=\"contact-info-item\"><div class=\"contact-info-icon\"><i class=\"fas fa-map-marker-alt\"></i></div><h3 class=\"contact-info-label\">Office Address</h3><p class=\"contact-info-value\">Capacity Building Commission,<br>20th, 21st &amp; 22nd Floor,<br>Jawahar Vyapar Bhavan,<br>Tolstoy Road, New Delhi – 110001</p></div></div><div class=\"col-lg-4 col-md-6\"><div class=\"contact-info-item\"><div class=\"contact-info-icon\"><i class=\"fas fa-phone-alt\"></i></div><h3 class=\"contact-info-label\">General Queries</h3><p class=\"contact-info-value\">Contact No.:<br><a class=\"contact-link\" href=\"tel:+911123701126\">+91 11 23701126</a></p></div></div><div class=\"col-lg-4 col-md-6\"><div class=\"contact-info-item\"><div class=\"contact-info-icon\"><i class=\"fas fa-envelope\"></i></div><h3 class=\"contact-info-label\">Email</h3><p class=\"contact-info-value\"><a class=\"contact-link\" href=\"mailto:cbc-dopt@gov.in\">cbc-dopt@gov.in</a></p></div></div></div></div></div></div><!-- Contact Form Section --><div class=\"contact-form-section-enhanced py-5\"><div class=\"container\"><div class=\"row\"><div class=\"col-lg-8 mx-auto\"><h2 class=\"form-section-title mb-4\">Your Feedback Matters</h2><form class=\"contact-form\"><div class=\"row g-3 mb-3\"><div class=\"col-md-6\"><label class=\"form-label\" for=\"name\">Name</label> <input class=\"form-control-enhanced\" type=\"text\" id=\"name\" required=\"\"></div><div class=\"col-md-6\"><label class=\"form-label\" for=\"email\">Email</label> <input class=\"form-control-enhanced\" type=\"email\" id=\"email\" required=\"\"></div></div><div class=\"mb-3\"><label class=\"form-label\" for=\"subject\">Subject</label> <input class=\"form-control-enhanced\" type=\"text\" id=\"subject\" required=\"\"></div><div class=\"mb-4\"><label class=\"form-label\" for=\"message\">Message</label> <textarea class=\"form-control-enhanced\" id=\"message\" rows=\"5\" required=\"\"></textarea></div><div class=\"text-center\"><button class=\"btn-submit-enhanced\" type=\"submit\">\r\n                <span>Send Message</span>\r\n                <i class=\"fas fa-paper-plane\"></i>\r\n              </button></div></form></div></div></div></div>', '', 'full_html'),
