('page', 0, 92, 216, 'en', 0, '<section class=\"container py-5\"><div class=\"karmayogi-content-wrapper\"><div class=\"row\"><div class=\"col-12\"><div class=\"mdos-nav-buttons\"><div class=\"mdos-nav-btn mdos-btn-1\"><a class=\"mdos-link\" href=\"/cbc/approach-paper\"><span class=\"mdos-btn-icon\"><i class=\"bi bi-file-earmark-text\"></i> </span><span class=\"mdos-btn-text\">APPROACH PAPER</span> <span class=\"mdos-btn-arrow\"><i class=\"bi bi-arrow-right\"></i>&nbsp;</span></a></div><div class=\"mdos-nav-btn mdos-btn-2\"><a class=\"mdos-link\" href=\"/cbc/acbp-process-manual\"><span class=\"mdos-btn-icon\"><i class=\"bi bi-journal-bookmark\"></i> </span><span class=\"mdos-btn-text\">PROCESS MANUAL</span> <span class=\"mdos-btn-arrow\"><i class=\"bi bi-arrow-right\"></i>&nbsp;</span></a></div><div class=\"mdos-nav-btn mdos-btn-3\"><a class=\"mdos-link\" href=\"/cbc/capacity-building-units\"><span class=\"mdos-btn-icon\"><i class=\"bi bi-building\"></i> </span><span class=\"mdos-btn-text\">CBU CREATED</span> <span class=\"mdos-btn-arrow\"><i class=\"bi bi-arrow-right\"></i>&nbsp;</span></a></div><div class=\"mdos-nav-btn mdos-btn-4\"><a class=\"mdos-link\" href=\"pages/frameworks/completed-acbp.html\"><span class=\"mdos-btn-icon\"><i class=\"bi bi-check-circle\"></i> </span><span class=\"mdos-btn-text\">COMPLETED CBP</span> <span class=\"mdos-btn-arrow\"><i class=\"bi bi-arrow-right\"></i>&nbsp;</span></a></div></div></div></div><div class=\"row\"><div class=\"col-12\"><div class=\"cbp-description-box\"><p class=\"cbp-description-text\">The Capacity Building Plan (CBP) of a ministry/department is a comprehensive document detailing all the interventions required to develop and enhance the competencies of individual officials within that ministry/department as well as the capacity of the ministry/department as a whole.</p></div></div></div></div></section>', '', 'full_html'),
('page', 0, 93, 194, 'en', 0, '<section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><h2 class=\"karmayogi-section-title\"><i class=\"bi bi-file-earmark-text-fill me-3\" style=\"color:#0063ae;\"></i>ACBP Approach Paper</h2><!-- Action Buttons --><div class=\"mb-4\" style=\"display:flex;flex-wrap:wrap;gap:15px;\"><a class=\"btn\" style=\"align-items:center;background-color:#0099ff;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;transition:all 0.3s ease;\" href=\"documents/ACBP_Approach-Paper.pdf\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Open PDF in New Tab </strong></a><a class=\"btn\" style=\"align-items:center;background-color:#28a745;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;transition:all 0.3s ease;\" href=\"documents/ACBP_Approach-Paper.pdf\" download=\"\"><strong><i class=\"bi bi-download\"></i> Download PDF&nbsp;</strong></a></div><!-- PDF Preview --><div class=\"document-viewer-wrapper\" style=\"background-color:#fff;border-radius:15px;box-shadow:0 4px 20px rgba(0, 0, 0, 0.08);margin-top:20px;padding:20px;\"><p><iframe style=\"border-radius:8px;border:1px solid #e9ecef;height:800px;width:100%;\" id=\"approachPaperViewer\" src=\"documents/ACBP_Approach-Paper.pdf#toolbar=1&amp;navpanes=1&amp;scrollbar=1\" frameborder=\"0\">\r\n          </iframe></p><div class=\"document-fallback\" style=\"background-color:#f8f9fa;border-radius:8px;display:none;margin-top:20px;padding:40px;text-align:center;\"><p class=\"mb-3\" style=\"color:#6c757d;font-size:1.1rem;\">PDF preview is not available in your browser. Please use the buttons above to open or download the document.</p><p><a class=\"btn\" style=\"align-items:center;background-color:#0099ff;border-radius:8px;border-style:none;color:#fff;display:inline-flex;gap:8px;padding:12px 30px;text-decoration:none;\" href=\"documents/ACBP_Approach-Paper.pdf\" target=\"_blank\"><strong><i class=\"bi bi-box-arrow-up-right\"></i> Open PDF&nbsp;</strong></a></p></div></div></div></div></section><script>\r\n// Handle PDF viewer fallback\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n  const viewer = document.getElementById(\'approachPaperViewer\');\r\n  const fallback = document.querySelector(\'.document-fallback\');\r\n  \r\n  // Check if iframe loads successfully\r\n  viewer.onerror = function() {\r\n    viewer.style.display = \'none\';\r\n    if (fallback) {\r\n      fallback.style.display = \'block\';\r\n    }\r\n  };\r\n  \r\n  // Check if PDF viewer is supported\r\n  setTimeout(function() {\r\n    try {\r\n      if (viewer.contentDocument === null || viewer.contentWindow.length === 0) {\r\n        // PDF may not be viewable in iframe, show fallback\r\n        if (fallback && viewer.src) {\r\n          viewer.style.display = \'none\';\r\n          fallback.style.display = \'block\';\r\n        }\r\n      }\r\n    } catch (e) {\r\n      // Cross-origin or other error, show fallback\r\n      if (fallback) {\r\n        viewer.style.display = \'none\';\r\n        fallback.style.display = \'block\';\r\n      }\r\n    }\r\n  }, 2000);\r\n});\r\n</script>', '', 'full_html'),
('page', 0, 100, 204, 'en', 0, '<section class=\"karmayogi-section-fullwidth karmayogi-vision-section\"><div class=\"container\"><div class=\"karmayogi-content-wrapper\"><h2 class=\"karmayogi-section-title left-aligned\" style=\"margin-bottom:30px;\">How to access on iGOT</h2><div class=\"row g-4 mt-4\"><!-- English Video --><div class=\"col-md-6\"><div class=\"video-card\"><div class=\"video-card-header\"><h4>HOW-TO VIDEO</h4></div><div class=\"video-card-title\"><h3>How to access the Rashtriya Karmayogi Program via the iGOT app?</h3></div><div class=\"video-card-body\"><div class=\"video-placeholder\"><p>Video Player Placeholder</p><p>Duration: 1:38</p></div><p><a class=\"video-watch-btn\" href=\"#\">Watch Video&nbsp;</a></p></div></div></div><!-- Hindi Video --><div class=\"col-md-6\"><div class=\"video-card\"><div class=\"video-card-header\"><h4>कैसे करें वीडियो</h4></div><div class=\"video-card-title\"><h3>आई-गॉट ऐप के माध्यम से राष्ट्रीय कर्मयोगी कार्यक्रम तक कैसे पहुंचें</h3></div><div class=\"video-card-body\"><div class=\"video-placeholder\"><p>Video Player Placeholder</p><p>Duration: 1:42</p></div><p><a class=\"video-watch-btn\" href=\"#\">Watch Video&nbsp;</a></p></div></div></div></div></div></div></section>', '', 'full_html');
