INSERT INTO `node_revision__field_event_description` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_event_description_value`, `field_event_description_summary`, `field_event_description_format`) VALUES
('event', 0, 5, 5, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani welcomed the USIBC - US India Business Council global board members for their annual meeting in Delhi this year. He explained the key tenets of Mission Karmayogi and its lasting impact on enhancing the state capacity.</p>', '', 'basic_html'),
('event', 0, 5, 6, 'en', 0, '<p>Capacity Building Commission\'s Secretary Hemang Jani welcomed the USIBC - US India Business Council global board members for their annual meeting in Delhi this year. He explained the key tenets of Mission Karmayogi and its lasting impact on enhancing the state capacity.</p>', '', 'basic_html'),
('event', 0, 6, 7, 'en', 0, '<p>Capacity Building Commission in collaboration with ISRO - Indian Space Research Organization launched the online phase of the ‘Building Science Leaders in India’ program today. The in-person phase will thereafter be held from 27th-30th September 2022.</p><p>&nbsp;</p><p>The ‘Building Science Leaders in India’ is a unique collaborative executive development programme for scientists at our Public funded R&amp;D organizations. The first batch has a cohort of 32 scientists from 7 scientific departments.</p>', '', 'basic_html'),
('video_gallery', 0, 7, 10, 'en', 0, '<p>Dr. Balasubramaniam (Member HR- Capacity Building Commission) on National Learning Week</p>', '', 'full_html'),
('video_gallery', 0, 8, 9, 'en', 0, '<p>Dr. Balasubramaniam (Member HR- Capacity Building Commission) on National Learning Week</p>', '', 'full_html'),
('video_gallery', 0, 8, 11, 'en', 0, '<p>National Learning Week 2024 introductory video.</p>', '', 'full_html'),
('video_gallery', 0, 8, 12, 'en', 0, '<p>National Learning Week 2024 introductory video.</p>', '', 'full_html'),
('our_collaboration_matters', 0, 24, 58, 'en', 0, '<p>Congratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'full_html'),
('our_collaboration_matters', 0, 25, 59, 'en', 0, '<p>OCongratulations to Rafi Ahmed Kidwai National Postal Academy (RKNPA) on being re-accredited with a 5-Star rating after QIP implementation done by CBC. Capacity Building Commission is proud to see institutions continue raising the bar for public service learning.</p>', '', 'full_html'),
('our_collaboration_matters', 0, 26, 60, 'en', 0, '<p>A shared culture of learning &amp; #SevaBhav is taking root across depts-breaking silos, making service more humane, more responsive &amp; more reliable. Governance is strengthening itself from within as we move toward a #ViksitBharat2047</p>', '', 'full_html'),
('our_collaboration_matters', 0, 26, 62, 'en', 0, '<p>A shared culture of learning &amp; #SevaBhav is taking root across depts-breaking silos, making service more humane, more responsive &amp; more reliable. Governance is strengthening itself from within as we move toward a #ViksitBharat2047</p>', '', 'full_html'),
('our_collaboration_matters', 0, 26, 63, 'en', 0, '<p>A shared culture of learning &amp; #SevaBhav is taking root across depts-breaking silos, making service more humane, more responsive &amp; more reliable. Governance is strengthening itself from within as we move toward a #ViksitBharat2047</p>', '', 'full_html'),
('our_collaboration_matters', 0, 27, 61, 'en', 0, '<p>The 𝗠𝗶𝗻𝗶𝘀𝘁𝗿𝘆 𝗼𝗳 𝗔𝘆𝘂𝘀𝗵 organized its first 𝐓𝐢𝐟𝐟𝐢𝐧 𝐁𝐚𝐢𝐭𝐡𝐚𝐤 under Mission Karmayogi. This informal interactive session was held under the Secretary, Ministry of Ayush, bringing together officers from different divisions.</p>', '', 'full_html'),
('opinions_do_matter', 0, 30, 66, 'en', 0, '<p>Dr. Anju Rathi Rana shares insights on building a culture of learning, seva bhav, and santushti in governance.</p>', '', 'full_html'),
('opinions_do_matter', 0, 31, 67, 'en', 0, '<p><span style=\"-webkit-text-stroke-width:0px;background-color:rgb(255, 255, 255);color:rgb(85, 85, 85);display:inline !important;float:none;font-family:Poppins, sans-serif;font-size:12.6px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:center;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">Madhavi Das shares how earning the prestigious 5-star \"Sarvotkrisht\" rating transformed NCA-F\'s operational excellence.</span></p>', '', 'full_html'),
('our_team', 0, 33, 69, 'en', 0, '<p>Ms. S. Radha Chauhan is a seasoned civil servant with 36+ years of leadership across public policy, fiscal governance, institutional reform, and digital transformation. She is a 1988 Batch IAS officer of UP Cadre (Retd.).</p>', '', 'full_html'),
('our_team', 0, 34, 70, 'en', 0, '<p>Dr. R Balasubramaniam (Balu) is a widely respected development expert, public policy analyst, leadership trainer and author. He has spent several decades working among forest-based tribal communities in southern India.</p>', '', 'full_html'),
('our_team', 0, 35, 71, 'en', 0, '<p>Dr. Alka Mittal is former CMD and Director (HR) of ONGC. She was also the Chairperson of ONGC Group of Companies viz. ONGC Videsh, MRPL, OPAL, OTPC, etc.</p>', '', 'full_html'),
('photo_gallery', 0, 79, 126, 'en', 0, '<p>IMPARD Workshop</p>', '', 'basic_html'),
('photo_gallery', 0, 79, 201, 'en', 0, '<p>IMPARD Workshop</p>', '', 'basic_html'),
('photo_gallery', 0, 80, 127, 'en', 0, '<p><strong>Jammu State level Workshops</strong></p>', '', 'basic_html'),
('photo_gallery', 0, 80, 200, 'en', 0, '<p><strong>Jammu State level Workshops</strong></p>', '', 'basic_html'),
('event', 0, 110, 219, 'en', 0, '<p>CBC organized a learning Design workshop for teams involved in the design of the Combined Mid-Career Training Program for All India Service Officers to brainstorm and revisit the design of the program based on the principles of Adult learning</p>', '', 'basic_html'),
('event', 0, 113, 223, 'en', 0, '<p>IDinsight has entered into a partnership with the Capacity Building Commission of India. IDinsight will support the CBC in preparing the Annual State of Civil Services Report, along with several others.</p>', '', 'basic_html'),
('event', 0, 114, 224, 'en', 0, '<p>The First Roundtable of Central Training Institutions was organised by CBC to kickstart collaboration activities amongst CTIs and reinforce the importance of transition to an era of integrated and desiloed learning ecosystem.</p><p>The workshop was graced by the presence of Hon\'ble MoS, Dr Jitendra Singh</p>', '', 'basic_html'),
('event', 0, 115, 225, 'en', 0, '<p>CBC, and Director NAAA Mr. Sunil Dadhe, had a discussion with mid-service Indian Audit and Account Services Officers and discussed policies to contain possible 3rd wave of COVID and roles of Audit in ensuring result oriented administrators.</p>', '', 'basic_html'),
('event', 0, 115, 226, 'en', 0, '<p>CBC, and Director NAAA Mr. Sunil Dadhe, had a discussion with mid-service Indian Audit and Account Services Officers and discussed policies to contain possible 3rd wave of COVID and roles of Audit in ensuring result oriented administrators.</p>', '', 'basic_html'),
('event', 0, 116, 227, 'en', 0, '<p>Singapore-India Partnership Office from the Ministry of Trade and Industry (Singapore) visited the Capacity Building Commission. The interaction between SIPO and CBC was held to discuss areas of collaboration for capacity building, and to support CBC\'s initiatives.</p>', '', 'basic_html'),
('event', 0, 117, 228, 'en', 0, '<p>Capacity Building Commission\'s team conducted a workshop at the National Institute of Communication Finance, a designated Central Training Institute for training of India Post and Telecommunications Accounts and Finance Service civil servants (IP&amp;TAFS).</p>', '', 'basic_html'),
('event', 0, 118, 229, 'en', 0, '<p>The Capacity Building Commission visited the National Academy of Audit and Accounts, housed at the historic campus \"Yarrows\" (NAAA), the apex Central Training Institute for training of Indian Audit &amp; Accounts Department (IA&amp;AD).</p>', '', 'basic_html'),
('event', 0, 120, 231, 'en', 0, '<p>CBC organised a meeting with Secretaries of pilot departments to brainstorm on the CBP approach</p>', '', 'basic_html'),
('event', 0, 121, 232, 'en', 0, '<p>We are delighted to announce that the Nation First Policy Research Centre (www.nationfirstpolicy.org) has entered into an MoU with the Capacity Building Commission. Nation First will be supporting us with providing resources at multiple levels and other initiatives.</p>', '', 'basic_html'),
('event', 0, 122, 233, 'en', 0, '<p>A workshop on approach to creation of Annual Capacity Building Plan was conducted by CBC to apprise the officials at the Ministry of Skill Development and Employment</p>', '', 'basic_html'),
('event', 0, 123, 234, 'en', 0, '<p>CBC’s approach to creation of CBPs at ministries and departments was presented to the Hon’ble Cabinet Secretary</p>', '', 'basic_html'),
('event', 0, 124, 235, 'en', 0, '<p>We are delighted to announce that the Indian School of Business (www.isb.edu) has entered into an MoU with the Capacity Building Commission. The Indian School of Business will be supporting us with creating learning resources, sectoral needs and data-driven impact assessment, and training of trainers and content partners and other outreach initiatives.</p>', '', 'basic_html'),
('event', 0, 125, 236, 'en', 0, '<p>The Capacity Building Commission, with Shri Pankaj Kumar, Chief Secretary, Shri Amrendra Kumar Rakesh, Additional Chief Secretary (Personnel), Shri Dhananjay Dwivedi, Secretary (NRI &amp; ARTD), Government of Gujarat and Shri Ramesh Chand Meena (DG SPIPA) at the Sardar Patel Institute of Public Administration (spipa.gujarat.gov.in) at Ahmedabad.</p>', '', 'basic_html'),
('event', 0, 126, 238, 'en', 0, '<p>Capacity Building Commission\'s team visited the National Institute of Defence Estates Management (NIDEM, nidem.dgde.gov.in), a Central Training Institute for training of Indian Defence Estates Service (IDES) Officers.</p><p>We conducted a workshop to test the draft CTI Functional Evaluation Framework, and learn from NIDEM\'s experience in operating a premier Civil Services Training Institute.</p>', '', 'basic_html'),
('event', 0, 127, 239, 'en', 0, '<p>Hon’ble Minister, Dr. Jitendra Singh chaired the first ever high-level Capacity Building Meeting of all the Science and Technology Ministries and Departments.<br>The meeting set the vision for capacity building of science ministries and departments under Government of India to achieve the Hon’ble Prime Minister’s vision of 5 trillion dollar economy and improving ease of living for all citizens.</p>', '', 'basic_html'),
('event', 0, 128, 240, 'en', 0, '<p>Shri Praveen Pardeshi a lecture on Wildlife crime detection and prevention to officers promoted into the IPS at the Sardar Vallabhai Patel National Police Academy Hyderabad. We discussed the application of DNA analysis of remnant of poached tigers to trace and link poachers to the crime.</p>', '', 'basic_html'),
('event', 0, 129, 241, 'en', 0, '<p>Capacity Building Commission\'s team visited the National Academy of Customs, Indirect Taxes and Narcotics (NACIN, www.nacin.gov.in), one of the 16 Zonal Training Institute\'s for training of Indian Revenue Service (IRS) Officers.</p><p>We conducted a workshop to test the draft CTI Functional Evaluation Framework, and learn from NACIN\'s experience in functioning as a premier Civil Services Zonal Training Institute.</p>', '', 'basic_html'),
('event', 0, 130, 242, 'en', 0, '<p>We are delighted to open the “Innovations in Public Administration” portal; inaugurated by Hon\'ble MOS (PP) Dr. Jitendra Singh, inviting all Government employees in the civil services of the Central, State or Local Government for an opportunity to showcase their innovations, initiatives and work that goes beyond the bounds of existing managerial systems.</p>', '', 'basic_html'),
('event', 0, 131, 243, 'en', 0, '<p>We are delighted to announce that Wadhwani AI (www.wadhwaniai.org) has entered into an MoU with the Capacity Building Commission. Wadhwani AI will be supporting us with knowledge and technology support in the area of artificial intelligence, machine learning and integrating emerging technologies for governance with resources at multiple levels.</p>', '', 'basic_html'),
('event', 0, 132, 244, 'en', 0, '<p>Capacity Building Commission\'s team visited the Indian Institute of Public Administration (IIPA) (www.iipa.org.in), an autonomous academic institution of national eminence for training, research and information dissemination in streams related to the ethos of Public Administration.</p><p>We conducted a workshop to decide the future course of action of the sub-committee on “Promotion of Knowledge Sharing” and it’s recommendations on the collaboration pillar of CBC\'s accreditation framework - \"National Standards for Civil Service Training Institutes\".</p>', '', 'basic_html'),
('event', 0, 133, 245, 'en', 0, '<p>We are delighted to announce that the Indian Institute of Management, Calcutta (www.iimcal.ac.in) has entered into an MoU with the Capacity Building Commission.</p><p>The Indian Institute of Management, Calcutta will be supporting us as a knowledge partner, providing customised leadership training programs, reports through impact-studies and imparting knowledge in areas of infrastructure, project management and communication.</p>', '', 'basic_html'),
('event', 0, 134, 246, 'en', 0, '<p>We are pleased to announce that Foundation for Advancing Science and Technology - India (www.fast-india.org) has signed an MoU with Capacity Building Commission to support capacity building in science, technology and innovation.</p>', '', 'basic_html'),
('event', 0, 135, 247, 'en', 0, '<p>The Embedding Effective Assessment of Training group had its first meeting to decide the structure of the report and its recommendations on training at the&nbsp;Indira Gandhi National Forest Academy&nbsp;Central Training Institute.</p>', '', 'basic_html'),
('event', 0, 136, 248, 'en', 0, '<p>The Science Capacity Building Cell setup by collaboration between Office of the Principal Scientific Adviser to the Government of India and Capacity Building Commission hosted the kick-off meeting for capacity building of science, technology and innovation institutions in Government of India</p>', '', 'basic_html');
