tion_matter_01.jpeg\" class=\"card-img-top\" alt=\"State Collaboration\">\r\n                  <div class=\"card-body\">\r\n                    <h5 class=\"card-title\">State Collaboration</h5>\r\n                    <p class=\"card-text\">States & UTs Partnership Event</p>\r\n                  </div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n          <button class=\"gallery-nav-btn gallery-nav-next\" aria-label=\"Next\">\r\n            <i class=\"fas fa-chevron-right\"></i>\r\n          </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div> --></div></section>', '', 'full_html');
