INSERT INTO `paragraph_revision__field_descriptions` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_descriptions_value`, `field_descriptions_summary`, `field_descriptions_format`) VALUES
('hero_section', 0, 2, 2, 'en', 0, '<p>Expert advisory services and research collaboration for evidence-based governance.</p>', '', 'full_html'),
('hero_section', 0, 4, 4, 'en', 0, '<p>India\'s first indigenous Public Sector Human Resource Management framework — tailored for building a capable, accountable, and citizen-centric civil service.</p>', '', 'full_html'),
('hero_section', 0, 5, 5, 'en', 0, '<p>Comprehensive capacity building interventions designed to reach large numbers of civil servants and create systemic change in governance.</p>', '', 'full_html'),
('hero_section', 0, 5, 6, 'en', 0, '<p>Comprehensive capacity building interventions designed to reach large numbers of civil servants and create systemic change in governance.</p>', '', 'full_html'),
('hero_section', 0, 5, 12, 'en', 0, '<p>Comprehensive capacity building interventions designed to reach large numbers of civil servants and create systemic change in governance.</p>', '', 'full_html'),
('hero_section', 0, 6, 7, 'en', 0, '<p>Fostering cognitive decolonisation and embedding India\'s civilizational wisdom into civil service capacity-building to create culturally rooted, purpose-driven, and ethically grounded governance.</p>', '', 'full_html'),
('hero_section', 0, 6, 8, 'en', 0, '<p>Fostering cognitive decolonisation and embedding India\'s civilizational wisdom into civil service capacity-building to create culturally rooted, purpose-driven, and ethically grounded governance.</p>', '', 'full_html'),
('hero_section', 0, 6, 9, 'en', 0, '<p>Fostering cognitive decolonisation and embedding India\'s civilizational wisdom into civil service capacity-building to create culturally rooted, purpose-driven, and ethically grounded governance.</p>', '', 'full_html'),
('hero_section', 0, 7, 10, 'en', 0, '<p>Comprehensive accreditation framework and quality improvement program for capacity building institutions.</p>', '', 'basic_html'),
('hero_section', 0, 8, 11, 'en', 0, '<p>A simplified guide for developing Annual Capacity Building Plans (ACBPs) for ministries and departments.</p>', '', 'basic_html'),
('hero_section', 0, 9, 13, 'en', 0, '<p>Advanced Case Writing and Teaching Programme under the Amrit Gyaan Kosh Initiative - A Capacity Building Commission Initiative in Collaboration with Stanford Leadership Academy for Development, Asian Development Bank India, and Asian Development Bank Institute.</p>', '', 'basic_html'),
('hero_section', 0, 10, 14, 'en', 0, '<p>A flagship Common Leadership Development Programme (CLDP) for senior executives of CPSEs, designed to build a sustained pipeline of leaders capable of assuming board-level responsibilities.</p>', '', 'basic_html'),
('hero_section', 0, 11, 15, 'en', 0, '<p>Building capacity of faculty in civil service training institutes to enhance training effectiveness and foster citizen-centricity.</p>', '', 'basic_html'),
('hero_section', 0, 12, 16, 'en', 0, '<p>A national movement to embed a culture of lifelong learning and continuous professional development within India\'s civil services, creating a future-ready, citizen-centric, and competency-driven workforce aligned with Viksit Bharat 2047.</p>', '', 'basic_html'),
('hero_section', 0, 13, 17, 'en', 0, '<p>A national movement to embed a culture of lifelong learning and continuous professional development within India\'s civil services, creating a future-ready, citizen-centric, and competency-driven workforce aligned with Viksit Bharat 2047.</p>', '', 'basic_html'),
('hero_section', 0, 14, 18, 'en', 0, '<p>description</p>', '', 'basic_html'),
('hero_section', 0, 15, 19, 'en', 0, '<p>description</p>', '', 'basic_html'),
