INSERT INTO `paragraph__field_descriptions` (`bundle`, `deleted`, `entity_id`, `revision_id`, `langcode`, `delta`, `field_descriptions_value`, `field_descriptions_summary`, `field_descriptions_format`) VALUES
('hero_section', 0, 2, 2, 'en', 0, '<p>Expert advisory services and research collaboration for evidence-based governance.</p>', '', 'full_html'),
('hero_section', 0, 4, 4, 'en', 0, '<p>India\'s first indigenous Public Sector Human Resource Management framework — tailored for building a capable, accountable, and citizen-centric civil service.</p>', '', 'full_html'),
('hero_section', 0, 5, 12, 'en', 0, '<p>Comprehensive capacity building interventions designed to reach large numbers of civil servants and create systemic change in governance.</p>', '', 'full_html'),
('hero_section', 0, 6, 9, 'en', 0, '<p>Fostering cognitive decolonisation and embedding India\'s civilizational wisdom into civil service capacity-building to create culturally rooted, purpose-driven, and ethically grounded governance.</p>', '', 'full_html'),
('hero_section', 0, 7, 10, 'en', 0, '<p>Comprehensive accreditation framework and quality improvement program for capacity building institutions.</p>', '', 'basic_html'),
('hero_section', 0, 8, 11, 'en', 0, '<p>A simplified guide for developing Annual Capacity Building Plans (ACBPs) for ministries and departments.</p>', '', 'basic_html'),
('hero_section', 0, 9, 13, 'en', 0, '<p>Advanced Case Writing and Teaching Programme under the Amrit Gyaan Kosh Initiative - A Capacity Building Commission Initiative in Collaboration with Stanford Leadership Academy for Development, Asian Development Bank India, and Asian Development Bank Institute.</p>', '', 'basic_html'),
('hero_section', 0, 10, 14, 'en', 0, '<p>A flagship Common Leadership Development Programme (CLDP) for senior executives of CPSEs, designed to build a sustained pipeline of leaders capable of assuming board-level responsibilities.</p>', '', 'basic_html'),
('hero_section', 0, 11, 15, 'en', 0, '<p>Building capacity of faculty in civil service training institutes to enhance training effectiveness and foster citizen-centricity.</p>', '', 'basic_html'),
('hero_section', 0, 12, 16, 'en', 0, '<p>A national movement to embed a culture of lifelong learning and continuous professional development within India\'s civil services, creating a future-ready, citizen-centric, and competency-driven workforce aligned with Viksit Bharat 2047.</p>', '', 'basic_html'),
('hero_section', 0, 13, 17, 'en', 0, '<p>A national movement to embed a culture of lifelong learning and continuous professional development within India\'s civil services, creating a future-ready, citizen-centric, and competency-driven workforce aligned with Viksit Bharat 2047.</p>', '', 'basic_html'),
('hero_section', 0, 14, 18, 'en', 0, '<p>description</p>', '', 'basic_html'),
('hero_section', 0, 15, 19, 'en', 0, '<p>description</p>', '', 'basic_html'),
('hero_section', 0, 16, 20, 'en', 0, '<p>description</p>', '', 'basic_html'),
('hero_section', 0, 17, 21, 'en', 0, '<p>description</p>', '', 'basic_html'),
('hero_section', 0, 18, 22, 'en', 0, '<p>A landmark initiative to strengthen India\'s civil service training ecosystem, bringing together training institutions, capacity building professionals, and stakeholders on a common platform for collaboration, knowledge exchange, and institutional strengthening.</p>', '', 'basic_html'),
('hero_section', 0, 19, 103, 'en', 0, '<p>A comprehensive program focused on instilling Seva Bhaav (spirit of service) and Svadharma (duty aligned with personal purpose) among civil servants to enhance citizen service delivery.</p>', '', 'basic_html'),
('hero_section', 0, 21, 27, 'en', 0, '<p>Strengthening Panchayati Raj Institutions through targeted capacity-building to empower grassroots governance and enable citizen-centric, responsive, and accountable local self-governance.</p>', '', 'basic_html'),
('hero_section', 0, 22, 28, 'en', 0, '<p>Creating a comprehensive capacity development ecosystem for over 4800 Urban Local Bodies to enhance local governance, service delivery, and support India\'s vision of Viksit Bharat by 2047.</p>', '', 'basic_html'),
('hero_section', 0, 23, 31, 'en', 0, '<p>Comprehensive capacity building support for states and union territories to strengthen governance and public service delivery.</p>', '', 'basic_html'),
('hero_section', 0, 24, 33, 'en', 0, '<p>Creating a competent civil service for effective public service delivery.<br>&nbsp;</p>', '', 'basic_html'),
('hero_section', 0, 25, 34, 'en', 0, '<p>Knowledge repository for the future ready bureaucracy of Amrit Kaal</p><ol><li><br>&nbsp;</li></ol>', '', 'basic_html'),
('hero_section', 0, 27, 87, 'en', 0, '<p>Be a part of Mission Karmayogi and contribute to transforming capacity building ecosystem in India.<br>&nbsp;</p>', '', 'basic_html'),
('hero_section', 0, 28, 52, 'en', 0, '<p>Partnerships for capacity building excellence.<br>&nbsp;</p>', '', 'basic_html'),
('hero_section', 0, 29, 56, 'en', 0, '<p>Get in touch with the Capacity Building Commission</p>', '', 'basic_html'),
('hero_section', 0, 30, 73, 'en', 0, '<p>Showcasing cutting-edge innovations and transformative practices in governance</p>', '', 'basic_html'),
('hero_section', 0, 31, 86, 'en', 0, '<p>Team CBC Meet the dedicated team driving capacity building initiatives across India</p>', '', 'full_html'),
('hero_section', 0, 32, 104, 'en', 0, '<p>Comprehensive capacity building support for ministries, departments, and organizations to develop competencies and organizational capabilities.</p>', '', 'basic_html'),
('hero_section', 0, 33, 97, 'en', 0, '<p>Strategic approach paper for capacity building initiatives in ministries, departments, and organizations.</p>', '', 'basic_html'),
('hero_section', 0, 34, 99, 'en', 0, '<p>Step-by-step video guide on how to access and use the iGOT (Integrated Government Online Training) platform.</p>', '', 'basic_html'),
('hero_section', 0, 35, 101, 'en', 0, '<p>Supporting training institutes across India in delivering effective capacity building programs for civil servants.</p>', '', 'basic_html');
